import { Body, Controller, InternalServerErrorException, Post, Res } from '@nestjs/common';
import type { Response } from 'express';
import { createLogger } from 'src/utils';

type RTCSessionDescriptionInit = {
  sdp: string;
  type: 'offer' | 'answer';
};

const WEBRTC_PORT = 8091

@Controller('webrtc-proxy')
export class WebrtcProxyController {

  private readonly logger = createLogger('WebrtcProxyController');

  @Post('session')
  async createSession(@Body() body: { offer: RTCSessionDescriptionInit }, @Res() res: Response) {
    try {
      const response = await fetch(`http://127.0.0.1:${WEBRTC_PORT}/api/session`, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify(body),
      });
  
      if (!response.ok) {
        const error = await response.text();
        this.logger.error(`Failed to create session: ${error}`);
        res.status(response.status).end(error);
        return
      }
      const data = await response.json();
      res.setHeader('Content-Type', 'application/json');
      return res.status(200).json(data);
    } catch (error) {
      this.logger.error(`Failed to create session: ${error}`);
      throw new InternalServerErrorException(error);
    }
  }
}
