import { Injectable, NotFoundException, type OnModuleInit } from '@nestjs/common';
import { defer, type Plugin, type PluginProperty } from '@scailx/shared';
import { $ } from 'bun';
import { resolve } from 'path';
import { JsonSettingsService } from 'src/common/json/json.service';
import {
  appConfig,
  createLogger,
  isHailoAccInstalled,
  PLUGINS_FILENAME,
} from 'src/utils';

@Injectable()
export class PluginsService implements OnModuleInit {
  private readonly logger = createLogger('PluginsService');

  private _plugins: Plugin[];
  public initDeferred = defer();
  constructor(private readonly jsonService: JsonSettingsService) {}

  async onModuleInit() {
    await this.readPlugins();
    this._plugins = await this.getPlugins();
    this.initDeferred.resolve();
  }

  async readPlugins() {
    const settingsFolderPath = resolve(
      appConfig.SCAILX_PORTAL_PROJECT_DATA,
      'settings',
    );
    try {
      await $`usr/bin/inspector ${settingsFolderPath}/plugins.json`
        .cwd(appConfig.SCAILX_EMBEDDED)
        .quiet();
    } catch (error) {
      this.logger.debug(`Error while reading plugins: ${error}`);
      throw new Error('Error while reading plugins');
    }
  }

  private async getPluginElements() {
    const { plugins } = await this.jsonService.readSettings<{ plugins: Plugin[] }>(
      PLUGINS_FILENAME,
    );
    const pluginElements = [];
    plugins.forEach((plugin) => {
      if (plugin.elements && plugin.elements.length) {
        pluginElements.push(...plugin.elements);
      }
    });
    return pluginElements.filter((plugin) => plugin.klass);
  }

  private filterProcessablePluginProperties(plugin: Plugin): Plugin {
    return {
      ...plugin,
      properties: plugin.properties.filter(
        (property) =>
          property.name !== 'name' &&
          property.name !== 'parent' &&
          property.flags.writable === true &&
          property.common_type_name !== null,
      ),
    };
  }

  async getPlugins(): Promise<Plugin[]> {
    const pluginElements = await this.getPluginElements();
    const isHailoInstalled = await isHailoAccInstalled();
    const plugins = pluginElements.map((plugin) =>
      this.filterProcessablePluginProperties(plugin),
    );
    if (isHailoInstalled) return plugins;

    return plugins.filter((plugin) => !plugin.name.includes('hailo'));
  }

  getPluginProperty(pluginName: string, propertyName: string): PluginProperty | null {
    const plugin = this._plugins.find((plugin) => plugin.name === pluginName);
    if (!plugin) {
      return null;
    }
    let property = null;
    if (propertyName.includes('::')) {
      const padPropertyName = propertyName.split('::')[1];
      const padsProps = plugin.pads
        .filter((pad) => !!pad.properties)
        .map((pad) => pad.properties)
        .flat();
      property = padsProps.find((property) => property.name === padPropertyName);
    } else {
      property = plugin.properties.find((property) => property.name === propertyName);
    }
    if (!property) {
      return null;
    }

    return property;
  }

  async getPluginsList(): Promise<string[]> {
    return this._plugins.map((plugin) => plugin.name);
  }

  async getPlugin(name: string): Promise<Plugin> {
    const plugin = this._plugins.find((plugin) => plugin.name === name);
    if (!plugin) {
      throw new NotFoundException(`Plugin ${name} not found`);
    }
    return this.filterProcessablePluginProperties(plugin);
  }
}
