import {
  BadRequestException,
  Injectable,
  InternalServerErrorException,
} from '@nestjs/common';
import { type CameraDevice, SCAILX_PORTAL_SETTINGS_FOLDER } from '@scailx/shared';
import { $ } from 'bun';
import { EOL } from 'os';
import { resolve } from 'path';
import { JsonSettingsService } from 'src/common/json/json.service';
import { appConfig, createLogger } from 'src/utils';
import { requiredControls } from './configs';
import type {
  CamConfig,
  CameraDeviceData,
  CameraParameters,
  CameraParamsDto,
  Control,
  Format,
  ResolutionCaps,
} from './types';

const CAMERA_PARAMS_FILENAME = 'camera_parameters';
const CAMERA_FORMATS_FILENAME = 'camera_formats';
const VIDEO_DEVICE_PARAMS: CameraDevice = '/dev/video0';
const VIDEO_DEVICE_FORMATS: CameraDevice = '/dev/video0';

@Injectable()
export class LocalCameraService {
  private readonly logger = createLogger('LocalCameraService');

  constructor(private readonly jsonService: JsonSettingsService) {}

  async getCameraList(): Promise<CameraDeviceData[]> {
    try {
      await $`python3 /usr/bin/create_cams_config.py`.quiet();
    } catch (error) {
      this.logger.warn('Error while creating camera list');
      this.logger.debug(error);
      throw new InternalServerErrorException('Error while creating camera list');
    }

    try {
      const cameraList = (await Bun.file(
        '/var/tmp/cams_config.json',
      ).json()) as CamConfig[];
      return cameraList
        .flatMap(([name, settingsList]) =>
          settingsList.map(({ device }) => ({
            name,
            device,
          })),
        )
        .reduce((acc, camConfig) => {
          if (acc.some((cam) => cam.device === camConfig.device)) {
            return acc;
          }
          return [...acc, camConfig];
        }, []);
    } catch (error) {
      this.logger.warn('Error while reading camera list');
      this.logger.debug(error);
      throw new InternalServerErrorException('Error while reading camera list');
    }
  }

  async getV4l2CameraList(): Promise<CameraDeviceData[]> {
    let devicesListText = '';
    try {
      devicesListText = await $`v4l2-ctl --list-devices`.quiet().text();
    } catch (error) {
      this.logger.warn('Error while getting devices list');
      this.logger.debug(error);
      if (error instanceof $.ShellError) {
        this.logger.info('Setting partial read result...');
        devicesListText = error.stdout.toString();
      }
    }

    if (!devicesListText) return [];

    const devicesList = await Promise.all(
      devicesListText
        .split('\n\n')
        .map((deviceData) => deviceData.trim())
        .filter((deviceData) => deviceData.length > 0)
        .map(async (deviceData) => {
          let [deviceName, ...devices] = deviceData
            .split(EOL)
            .map((line) => line.trim())
            .filter((line) => line.length > 0);

          const validDevices = [];
          const displayedName = deviceName.slice(0, deviceName.search(/\(|:/));
          for (const device of devices) {
            if (!device.startsWith('/dev/')) {
              continue;
            }
            try {
              const devicePropertiesText = await $`v4l2-ctl --device ${device} --all`
                .quiet()
                .text();
              if (
                devicePropertiesText.includes('Format Video Capture') &&
                (devicePropertiesText.includes('User Controls') ||
                  devicePropertiesText.includes('Camera Controls'))
              ) {
                validDevices.push(device);
              }
            } catch (error) {
              continue;
            }
          }

          if (validDevices.length === 1) {
            return {
              name: displayedName,
              device: validDevices[0] as `/dev/${string}`,
            };
          } else if (validDevices.length > 1) {
            return validDevices.map((device, index) => ({
              name: `${displayedName}-${index + 1}`,
              device: device as `/dev/${string}`,
            }));
          } else {
            return [];
          }
        }),
    );

    return devicesList.flat();
  }

  async getFormats(device = VIDEO_DEVICE_FORMATS): Promise<Format[]> {
    this.logger.info('Reading camera formats from json file...');

    const scailxEmbeddedBuildFolder = appConfig.SCAILX_EMBEDDED;
    if (!scailxEmbeddedBuildFolder) {
      const message =
        "SCAILX_EMBEDDED environment variable is not set, can't read camera formats and controls";
      this.logger.warn(message);
      throw new InternalServerErrorException(message);
    }

    if (!device || !device.startsWith('/dev/')) {
      const errorMessage = 'Incorrect video device: ' + device;
      this.logger.warn(errorMessage);
      throw new BadRequestException(errorMessage);
    }

    const dataFolder = appConfig.SCAILX_PORTAL_PROJECT_DATA;
    const cameraFormatsFilePath = resolve(
      dataFolder,
      SCAILX_PORTAL_SETTINGS_FOLDER,
      `${CAMERA_FORMATS_FILENAME}.json`,
    );
    const cameraFormatsToolPath = resolve(
      scailxEmbeddedBuildFolder,
      'usr',
      'bin',
      'v4l2_formats',
    );
    try {
      await $`${cameraFormatsToolPath} ${device} ${cameraFormatsFilePath}`.quiet();
    } catch (error) {
      const message = `Can't read camera formats from device ${device}`;
      this.logger.warn(message, error);
      throw new BadRequestException(message);
    }

    try {
      const { formats } = await this.jsonService.readSettings<CameraParameters>(
        CAMERA_FORMATS_FILENAME,
      );
      if (formats.some((format) => format.resolution.length === 0)) {
        const defaultResolutions =
          await this.jsonService.readSettings<ResolutionCaps[]>('resolutions');
        for (const format of formats) {
          format.resolution = defaultResolutions;
        }
      }
      return formats;
    } catch (error) {
      this.logger.debug(error);
      const errorMessage = 'Camera params file is missing';
      this.logger.warn(errorMessage);
      throw new InternalServerErrorException(errorMessage);
    }
  }

  async getControls(device = VIDEO_DEVICE_PARAMS): Promise<Control[]> {
    const scailxEmbeddedBuildFolder = appConfig.SCAILX_EMBEDDED;
    if (!scailxEmbeddedBuildFolder) {
      const message =
        "SCAILX_EMBEDDED environment variable is not set, can't read camera formats and controls";
      this.logger.warn(message);
      throw new InternalServerErrorException(message);
    }

    if (!device || !device.startsWith('/dev/')) {
      const errorMessage = 'Incorrect video device: ' + device;
      this.logger.warn(errorMessage);
      throw new BadRequestException(errorMessage);
    }

    const dataFolder = appConfig.SCAILX_PORTAL_PROJECT_DATA;

    const cameraParamsFilePath = resolve(
      dataFolder,
      SCAILX_PORTAL_SETTINGS_FOLDER,
      `${CAMERA_PARAMS_FILENAME}.json`,
    );
    const cameraParamsToolPath = resolve(
      scailxEmbeddedBuildFolder,
      'usr',
      'bin',
      'v4l2_params',
    );
    try {
      await $`${cameraParamsToolPath} ${device} ${cameraParamsFilePath}`.quiet();
    } catch (error) {
      this.logger.warn(`Can't read camera params from device ${device}:`, error);
      throw new BadRequestException(`Can't read camera params from device ${device}`);
    }

    let cameraParams;
    try {
      cameraParams =
        await this.jsonService.readSettings<CameraParameters>(CAMERA_PARAMS_FILENAME);
    } catch (error) {
      this.logger.debug(error);
      const errorMessage = 'Camera params file is missing';
      this.logger.warn(errorMessage);
      throw new InternalServerErrorException(errorMessage);
    }

    let controls = cameraParams.controls;

    controls = controls.filter((control) => requiredControls.includes(control.control));
    try {
      for (const control of controls) {
        const id = control.control.replace(/(,\s)|\s/g, '_').toLowerCase();
        const deviceControlText = await $`v4l2-ctl --device ${device} --get-ctrl ${id}`
          .quiet()
          .text();
        const [, value] = deviceControlText.trim().split(': ');
        control.value = +value;
        control.id = id;
      }
    } catch (error) {
      const errorMessage = "Can't read camera control values via v4l2-ctl";
      this.logger.warn(errorMessage);
      throw new InternalServerErrorException(errorMessage);
    }
    return controls;
  }

  async setControls(cameraParams: CameraParamsDto): Promise<void> {
    const { device, params } = cameraParams;

    this.logger.info(
      'Setting camera controls: ' + JSON.stringify(cameraParams, null, 2),
    );

    const setCtls = [];

    for (const controlValue of params) {
      const { id, value } = controlValue;
      setCtls.push(`${id}=${+value}`);
    }
    try {
      await $`v4l2-ctl --device ${device} --set-ctrl ${setCtls.join(',')}`.quiet();
    } catch (error) {
      const errorMessage = 'Cant set camera controls via v4l2-ctl';
      this.logger.warn(errorMessage);
      this.logger.debug(error);
      throw new Error(errorMessage);
    }
  }
}
