import { Injectable, NotFoundException, type OnModuleInit } from '@nestjs/common';
import { readdir, readFile } from 'node:fs/promises';
import { resolve } from 'node:path';
import {
  AI_PROCESSING_PRESETS_FOLDER,
  appConfig,
  createLogger,
  HAILO_PRESETS_FOLDER,
  INPUT_PRESETS_FOLDER,
  isHailoInstalled,
  NN_STREAMER_PRESETS_FOLDER,
  OUTPUT_PRESETS_FOLDER,
  PRESETS_FOLDER,
} from 'src/utils';
import { PipelineService } from '../pipeline.service';
import type {
  AIProcessingPresetOption,
  Platform,
  PresetDto,
  PresetOption,
} from '../types';

const presetsFolder = resolve(appConfig.SCAILX_PORTAL_PROJECT_DATA, PRESETS_FOLDER);
const labelsFile = resolve(presetsFolder, 'labels.json');
const inputPresetsFolder = resolve(presetsFolder, INPUT_PRESETS_FOLDER);
const nnStreamerPresetsFolder = resolve(
  presetsFolder,
  AI_PROCESSING_PRESETS_FOLDER,
  NN_STREAMER_PRESETS_FOLDER,
);
const hailoPresetsFolder = resolve(
  presetsFolder,
  AI_PROCESSING_PRESETS_FOLDER,
  HAILO_PRESETS_FOLDER,
);
const commonOutputPresetsFolder = resolve(presetsFolder, OUTPUT_PRESETS_FOLDER);

@Injectable()
export class PresetsService implements OnModuleInit {
  private readonly logger = createLogger('PresetsService');
  private _labelsMap: Record<string, string> = {};

  constructor(private readonly pipelineService: PipelineService) {}

  async onModuleInit() {
    await this.pipelineService.initDeferred.promise;
    try {
      this._labelsMap = (await Bun.file(labelsFile).json()) as Record<string, string>;
    } catch (error) {
      this.logger.warn("Can't read labels file, using default labels");
    }
  }

  async getInputPresetsList(): Promise<PresetOption[]> {
    const inputPresets = await readdir(inputPresetsFolder);
    return this.mapPresetFileNamesToOptions(inputPresets);
  }

  async getAIProcessingPresetsList(): Promise<AIProcessingPresetOption[]> {
    const presetOptions = await this.getNNStreamerPresetsList();
    if (await isHailoInstalled()) {
      const hailoPresetOptions = await this.getHailoPresetsList();
      presetOptions.push(...hailoPresetOptions);
    }
    return presetOptions;
  }

  private async getNNStreamerPresetsList(): Promise<AIProcessingPresetOption[]> {
    const nnStreamerPresets = await readdir(nnStreamerPresetsFolder);
    return this.mapPresetFileNamesToOptions(nnStreamerPresets).map((option) => ({
      ...option,
      platform: 'nnstreamer',
    }));
  }

  private async getHailoPresetsList(): Promise<AIProcessingPresetOption[]> {
    const hailoPresets = await readdir(hailoPresetsFolder);
    return this.mapPresetFileNamesToOptions(hailoPresets).map((option) => ({
      ...option,
      platform: 'hailo',
    }));
  }

  async getOutputPresetsList(
    platform: Platform,
    aiProcessingPresetName: string,
  ): Promise<PresetOption[]> {
    const commonOutputPresets = await this.getCommonOutputPresetsList();
    const presetFolder = resolve(
      presetsFolder,
      AI_PROCESSING_PRESETS_FOLDER,
      platform,
      aiProcessingPresetName,
    );
    let presetSpecificOutputs: string[] = [];
    try {
      presetSpecificOutputs = (await readdir(presetFolder)).filter(
        (file) => file.endsWith('.txt') && !file.startsWith('base'),
      );
    } catch (error) {}
    return this.mapPresetFileNamesToOptions(presetSpecificOutputs).concat(
      commonOutputPresets,
    );
  }

  private async getCommonOutputPresetsList(): Promise<PresetOption[]> {
    const commonOutputPresets = await readdir(commonOutputPresetsFolder);

    return this.mapPresetFileNamesToOptions(commonOutputPresets);
  }

  private mapPresetFileNamesToOptions(presets: string[]): PresetOption[] {
    return presets.map((preset) => {
      const name = preset.replace('.txt', '');
      return {
        label: this._labelsMap[name] ?? name,
        name,
      };
    });
  }

  async getInputPreset(name: string): Promise<PresetDto> {
    let preset: string = '';
    try {
      preset = await readFile(resolve(inputPresetsFolder, name + '.txt'), 'utf8');
    } catch (error) {
      throw new NotFoundException(`Input preset ${name} not found`);
    }
    return {
      preset,
    };
  }

  async getAIProcessingPreset(platform: Platform, name: string): Promise<PresetDto> {
    let preset: string = '';
    try {
      preset = await readFile(
        resolve(
          presetsFolder,
          AI_PROCESSING_PRESETS_FOLDER,
          platform,
          name,
          'base.txt',
        ),
        'utf8',
      );
    } catch (error) {
      throw new NotFoundException(`AI processing preset ${name} not found`);
    }
    return {
      preset,
    };
  }

  async getOutputPreset(
    platform: Platform,
    aiProcessingPresetName: string,
    name: string,
  ): Promise<PresetDto> {
    let preset: string = '';
    const commonOutputPresets = await this.getCommonOutputPresetsList();
    if (commonOutputPresets.some((preset) => preset.name === name)) {
      try {
        preset = await readFile(resolve(OUTPUT_PRESETS_FOLDER, name + '.txt'), 'utf8');
      } catch (error) {
        throw new NotFoundException(`Output preset ${name} not found`);
      }
    } else {
      try {
        const aiProcessingPresetFolder = resolve(
          presetsFolder,
          AI_PROCESSING_PRESETS_FOLDER,
          platform,
          aiProcessingPresetName,
        );
        preset = await readFile(
          resolve(aiProcessingPresetFolder, name + '.txt'),
          'utf8',
        );
      } catch (error) {
        throw new NotFoundException(`Output preset ${name} not found`);
      }
    }

    return {
      preset,
    };
  }
}
