import * as jwt from 'jsonwebtoken';
import type winston from 'winston';

type ProxyTlsConfig = {
  key: string; // file path
  cert: string; // file path
};

type ProxyTarget = {
  name: string;
  proxyPort: number;
  target: string; // e.g. "http://127.0.0.1:1984"
  jwtSecret: string;
  cookieName?: string; // default: "accessToken"
  tls?: ProxyTlsConfig;
};

export type ProxyWsData = {
  upstreamUrl: string;
  headers: Record<string, string>;
  protocols?: string[];
  user?: any;
};

const HOP_BY_HOP = new Set([
  'connection',
  'keep-alive',
  'proxy-authenticate',
  'proxy-authorization',
  'te',
  'trailers',
  'transfer-encoding',
  'upgrade',
]);

const WS_HANDSHAKE_SKIP = new Set([
  'connection',
  'upgrade',
  'sec-websocket-key',
  'sec-websocket-version',
  'sec-websocket-extensions',
]);

function stripHopByHop(headers: Headers) {
  for (const key of Array.from(headers.keys())) {
    if (HOP_BY_HOP.has(key.toLowerCase())) headers.delete(key);
  }
}

function parseCookies(cookieHeader: string | null): Record<string, string> {
  const out: Record<string, string> = {};
  if (!cookieHeader) return out;

  const parts = cookieHeader.split(';');
  for (const p of parts) {
    const idx = p.indexOf('=');
    if (idx === -1) continue;
    const k = p.slice(0, idx).trim();
    const v = p.slice(idx + 1).trim();
    if (!k) continue;
    out[k] = decodeURIComponent(v);
  }
  return out;
}

function verifyRequestJwt(req: Request, jwtSecret: string, cookieName = 'accessToken') {
  const cookies = parseCookies(req.headers.get('cookie'));
  const token = cookies[cookieName];

  if (!token) return { ok: false as const };

  try {
    const payload = jwt.verify(token, jwtSecret);
    return { ok: true as const, payload };
  } catch {
    return { ok: false as const };
  }
}

// Clone request headers for HTTP proxying
function cloneHttpHeaders(incoming: Headers, upstreamUrl: URL): Headers {
  const out = new Headers();

  for (const [k, v] of incoming.entries()) {
    if (HOP_BY_HOP.has(k.toLowerCase())) continue;
    out.set(k, v);
  }

  // Align host to upstream
  out.set('host', upstreamUrl.host);

  return out;
}

// Clone headers for upstream WS handshake
function cloneWsHeaders(incoming: Headers, upstreamUrl: URL): Record<string, string> {
  const out: Record<string, string> = {};

  for (const [k, v] of incoming.entries()) {
    const lower = k.toLowerCase();
    if (WS_HANDSHAKE_SKIP.has(lower)) continue;
    if (lower === 'sec-websocket-protocol') continue; // handled separately
    out[k] = v;
  }

  out['host'] = upstreamUrl.host;

  const origin = incoming.get('origin');
  if (origin) out['origin'] = origin;

  return out;
}

function parseProtocols(h: Headers): string[] | undefined {
  const raw = h.get('sec-websocket-protocol');
  if (!raw) return undefined;
  const protocols = raw
    .split(',')
    .map((s) => s.trim())
    .filter(Boolean);
  return protocols.length ? protocols : undefined;
}

export function startBunNativeProxy(
  cfg: ProxyTarget,
  logger: winston.Logger,
): Bun.Server<ProxyWsData> {
  const cookieName = cfg.cookieName ?? 'accessToken';

  const targetHttp = new URL(cfg.target);
  const targetWsBase = new URL(cfg.target.replace(/^http/i, 'ws'));

  async function handleHttp(req: Request): Promise<Response> {
    const url = new URL(req.url);
    const upstreamUrl = new URL(url.pathname + url.search, targetHttp);
    const headers = cloneHttpHeaders(req.headers, upstreamUrl);

    const init: RequestInit = {
      method: req.method,
      headers,
      redirect: 'manual',
    };

    if (req.method !== 'GET' && req.method !== 'HEAD') {
      init.body = req.body;
    }

    const upstreamResp = await fetch(upstreamUrl, init);

    const respHeaders = new Headers(upstreamResp.headers);
    stripHopByHop(respHeaders);

    return new Response(upstreamResp.body, {
      status: upstreamResp.status,
      statusText: upstreamResp.statusText,
      headers: respHeaders,
    });
  }

  const serverOptions: Parameters<typeof Bun.serve<ProxyWsData, any>>[0] = {
    port: cfg.proxyPort,
    hostname: '0.0.0.0',

    // Enable HTTPS if tls is provided
    ...(cfg.tls
      ? {
          tls: {
            key: Bun.file(cfg.tls.key),
            cert: Bun.file(cfg.tls.cert),
          },
        }
      : {}),

    fetch(req, server) {
      const url = new URL(req.url);
      const upgrade = req.headers.get('upgrade')?.toLowerCase();

      // --- Auth logic ---
      const auth = verifyRequestJwt(req, cfg.jwtSecret, cookieName);
      if (!auth.ok) {
        return new Response('Unauthorized', { status: 401 });
      }

      if (upgrade === 'websocket') {
        const upstreamUrl = new URL(url.pathname + url.search, targetWsBase);
        const protocols = parseProtocols(req.headers);
        const headers = cloneWsHeaders(req.headers, upstreamUrl);

        const ok = server.upgrade(req, {
          data: {
            upstreamUrl: upstreamUrl.toString(),
            headers,
            protocols,
            user: auth.payload, // mimic (req as any).user assignment
          },
        });

        return ok
          ? undefined
          : new Response('WebSocket upgrade failed', { status: 400 });
      }

      return handleHttp(req);
    },

    websocket: {
      idleTimeout: 120,
      maxPayloadLength: 1024 * 1024 * 16,

      async open(ws) {
        const { upstreamUrl, headers, protocols } = ws.data;

        // Bun server-side WS client supports custom headers.
        const upstream = new WebSocket(upstreamUrl, {
          headers,
          ...(protocols ? { protocols } : {}),
        } as any);

        (ws as any).upstream = upstream;
        upstream.binaryType = 'arraybuffer';

        upstream.addEventListener('message', (evt) => ws.send(evt.data as any));
        upstream.addEventListener('close', () => {
          try {
            ws.close(1000);
          } catch {}
        });

        upstream.addEventListener('error', () => {
          try {
            ws.close(1011);
          } catch {}
        });
      },

      message(ws, message) {
        const upstream = (ws as any).upstream as WebSocket | undefined;
        if (upstream && upstream.readyState === WebSocket.OPEN) {
          upstream.send(message as any);
        }
      },

      close(ws) {
        const upstream = (ws as any).upstream as WebSocket | undefined;
        try {
          upstream?.close();
        } catch {}
      },
    },
  };

  const proxyServer = Bun.serve(serverOptions);

  logger.debug(`${cfg.proxyPort} -> ${cfg.target}`);

  return proxyServer;
}
