import { Module } from '@nestjs/common';
import { MulterModule } from '@nestjs/platform-express';
import {
  SCAILX_PORTAL_MODELS_FOLDER,
  SCAILX_PORTAL_SCRIPTS_FOLDER,
  SCAILX_PORTAL_SD_CARD_FOLDER,
  SCAILX_PORTAL_TEMP_FOLDER,
  SCAILX_PORTAL_TEXT_FILES_FOLDER,
  SCAILX_PORTAL_VIDEO_FOLDER,
} from '@scailx/shared';
import { diskStorage } from 'multer';
import { resolve } from 'path';
import { appConfig, getSDCardStatus } from 'src/utils';
import { FilesController } from './files.controller';
import { FilesService } from './files.service';

@Module({
  imports: [
    MulterModule.register({
      storage: diskStorage({
        destination: async (req, _file, cb) => {
          const dataFolder = appConfig.SCAILX_PORTAL_PROJECT_DATA;
          const endpoint = req.path.split('/').at(-1);
          switch (endpoint) {
            case SCAILX_PORTAL_VIDEO_FOLDER:
              cb(null, resolve(dataFolder, SCAILX_PORTAL_VIDEO_FOLDER));
              break;

            case SCAILX_PORTAL_MODELS_FOLDER:
              cb(null, resolve(dataFolder, SCAILX_PORTAL_MODELS_FOLDER));
              break;

            case SCAILX_PORTAL_TEXT_FILES_FOLDER:
              cb(null, resolve(dataFolder, SCAILX_PORTAL_TEXT_FILES_FOLDER));
              break;

            case SCAILX_PORTAL_SCRIPTS_FOLDER:
              cb(null, resolve(dataFolder, SCAILX_PORTAL_SCRIPTS_FOLDER));
              break;

            case SCAILX_PORTAL_SD_CARD_FOLDER: {
              try {
                const { mountPoint } = await getSDCardStatus();
                cb(null, mountPoint);
              } catch (error) {
                if (error instanceof Error) {
                  cb(error, null);
                }
              } finally {
                break;
              }
            }

            default:
              cb(null, resolve(dataFolder, SCAILX_PORTAL_TEMP_FOLDER));
              break;
          }
        },
        filename: (_req, file, cb) => {
          cb(null, file.originalname);
        },
      }),
    }),
  ],
  controllers: [FilesController],
  providers: [FilesService],
})
export class FilesModule {}
