import {
  BadRequestException,
  Injectable,
  InternalServerErrorException,
  type OnApplicationShutdown,
  type OnModuleDestroy,
  type OnModuleInit,
} from '@nestjs/common';
import { EventEmitter2 } from '@nestjs/event-emitter';
import type { Pipeline, PipelineComponentsDto } from '@scailx/shared';
import { defer, PIPELINE_FILENAME, type PluginProperty } from '@scailx/shared';
import { $ } from 'bun';
import * as os from 'node:os';
import { resolve } from 'path';
import { combineLatest, Subject, Subscription } from 'rxjs';
import { Go2rtcService } from 'src/common/go2rtc/go2rtc.service';
import { JsonSettingsService } from 'src/common/json/json.service';
import { wait } from 'src/common/utils';
import {
  appConfig,
  createLogger,
  PIPELINE_FPS_EVENT_NAME,
  PIPELINE_LATENCY_EVENT_NAME,
  PIPELINE_STATUS_EVENT_NAME,
  readStream,
} from 'src/utils';
import { PluginsService } from './plugins/plugins.service';
import type { Status } from './types';

@Injectable()
export class PipelineService
  implements OnModuleInit, OnModuleDestroy, OnApplicationShutdown
{
  private readonly logger = createLogger('PipelineService');
  private _status = 'stopped';
  private _isShutdown = false;

  private _statusMessage = '';
  private _pipelineProcess: null | Bun.Subprocess = null;
  private _gstreamerLogger = createLogger('Gstreamer', 'gstreamer');
  private _latencyCounters$: Record<string, Subject<number>> = {};
  private _latencyCounterSub: Subscription | null = null;
  public initDeferred = defer();

  constructor(
    private readonly jsonService: JsonSettingsService,
    private readonly pluginsService: PluginsService,
    private readonly go2rtcService: Go2rtcService,
    private readonly eventEmitter: EventEmitter2,
  ) {}

  async onModuleInit() {
    await this.jsonService.initSettings(PIPELINE_FILENAME, {
      components: [],
      inputIds: [],
    });

    await this.go2rtcService.configureGo2Rtc();
    await wait(500); // wait for go2rtc to restart

    await this.pluginsService.initDeferred.promise;
    this.initDeferred.resolve();
  }

  public get status(): string {
    return this._status;
  }

  public set status(status: string) {
    this._status = status;
    this.eventEmitter.emit(PIPELINE_STATUS_EVENT_NAME, status);
  }

  async init() {
    await this.startPipeline();
  }

  async onModuleDestroy() {
    await this.onDestroy();
  }

  async onApplicationShutdown() {
    await this.onDestroy();
  }

  async onDestroy() {
    if (this._isShutdown) return;
    this._isShutdown = true;
    try {
      await this.stopPipeline();
    } catch (error) {
      this.logger.warn(`Error while stopping pipeline: ${error}`);
    }
  }

  getStatus(): Status {
    return {
      status: this.status,
      message: this._statusMessage,
    };
  }

  getPluginPropertyHandler(
    property: PluginProperty | null,
  ): (value: unknown) => unknown {
    switch (property?.common_type_name) {
      case 'string':
        return (value: string) => `"${value}"`;
      case 'int':
        return (value: number) => Number(value);
      case 'float':
        return (value: number) => Number(value);
      case 'bool':
        return (value: boolean) => Boolean(value);
      case 'enum':
        return (value: string) => value;
      case 'fractional':
        return (value: [number, number]) =>
          Array.isArray(value) ? value.slice(0, 2).join('/') : value;
      case 'flags':
        return (value: (string | number)[]) =>
          Array.isArray(value) ? value.join('+') : value;
      // case 'array':
      //   return (value: string) => value;
      // case 'struct':
      //   return (value: string) => value;
      // case 'caps':
      //   return (value: string) => value;
      default:
        return (value: unknown) => `"${value}"`;
    }
  }

  private mapSettingsToGst(element: string, settings: Record<string, unknown>): string {
    if (!settings) return '';
    return Object.entries(settings)
      .map(([key, value]) => {
        const property: PluginProperty | null = this.pluginsService.getPluginProperty(
          element,
          key,
        );

        // HOTFIX: zorder property behaves differently if not set explicitly, so the actual default should be null
        if (
          element === 'compositor' &&
          property &&
          property.name.endsWith('::zorder')
        ) {
          property.default = null;
        }

        // FIX: always explicitly set device
        if (element === 'v4l2src' && property && property.name === 'device') {
          property.default = null;
        }

        const defaultValue = property?.default;
        const propertyHandler = this.getPluginPropertyHandler(property);
        const propertyValue = propertyHandler(value);
        return value == defaultValue || propertyValue === defaultValue
          ? ''
          : `${key}=${propertyValue}`;
      })
      .filter((setting) => !!setting)
      .join(' ');
  }

  buildPipeline(
    components: PipelineComponentsDto,
    inputIds: string[],
    gstPipelines = [],
  ): string[] {
    let currentId: string | undefined;
    for (const inputId of inputIds) {
      currentId = inputId;
      let gstPipeline = '';
      while (currentId) {
        if (gstPipelines.some((element) => element.includes(`name=${currentId}`))) {
          gstPipeline += `${currentId}. `;
          currentId = undefined;
          break;
        }

        const component = components.find((component) => component.id === currentId);
        if (!component) {
          throw new Error(`Component ${currentId} not found`);
        }
        const { type: nodeType, id } = component;
        const { type: elementType, settings, outputIds, binRootId } = component.data;
        if (nodeType === 'element') {
          gstPipeline += `${elementType} name=${id} ${this.mapSettingsToGst(elementType, settings)}`;
        } else if (nodeType === 'bin') {
          const binPipeline = this.buildPipeline(components, [binRootId]);
          gstPipeline += `bin. ( name=${id} ${binPipeline.join(' ')} )`;
        }

        if (outputIds.length === 1) {
          gstPipeline += ' ! ';
          currentId = outputIds[0];
        } else if (outputIds.length > 1) {
          gstPipelines.push(gstPipeline);
          gstPipeline = '';
          gstPipelines = this.buildPipeline(components, outputIds, gstPipelines).map(
            (pipeline) => {
              const isStartsWithOutputId = outputIds.some((outputId) => {
                const elementSearchPattern = new RegExp(
                  `^\\w+\\sname=${outputId}`,
                  'g',
                );
                const binSearchPattern = new RegExp(
                  `^bin\\.\\s\\(\\sname=${outputId}`,
                  'g',
                );
                // TODO: uncomment when request pad name refs are supported
                // const refSearchPattern = new RegExp(`^${outputId}\.`, 'g');
                const elementSearchResult = pipeline
                  .trim()
                  .search(elementSearchPattern);
                const binSearchResult = pipeline.trim().search(binSearchPattern);
                // const refSearchResult = pipeline.trim().search(refSearchPattern);
                return elementSearchResult !== -1 || binSearchResult !== -1; // || refSearchResult !== -1;
              });
              if (isStartsWithOutputId) {
                return `${id}. ! ${pipeline}`;
              }
              return pipeline;
            },
          );
          currentId = undefined;
        } else {
          currentId = undefined;
          break;
        }
      }
      gstPipelines.push(gstPipeline);
      gstPipeline = '';
    }

    return gstPipelines.filter((pipeline) => !!pipeline);
  }

  async setupCounters(components: PipelineComponentsDto) {
    const scailxEmbeddedBuildFolder = appConfig.SCAILX_EMBEDDED;
    if (!scailxEmbeddedBuildFolder) {
      throw new InternalServerErrorException('SCAILX_EMBEDDED is not set');
    }

    const trackLatencyComponentsIds = [];
    components.forEach((component) => {
      if (component.data.trackLatency) {
        trackLatencyComponentsIds.push(component.id);
        this._latencyCounters$[component.id] = new Subject<number>();
      }
    });

    const countersFilePath = resolve(scailxEmbeddedBuildFolder, 'counters.txt');
    const countersFile = await Bun.file(countersFilePath);
    await countersFile.write(trackLatencyComponentsIds.join('\n'));

    const latencyCountersArr = Object.values(this._latencyCounters$);

    if (latencyCountersArr.length) {
      this.logger.info(
        `Setting up counters for components: ${trackLatencyComponentsIds.join(', ')}`,
      );
      this._latencyCounterSub = combineLatest(latencyCountersArr).subscribe(
        ([...counters]) => {
          const totalLatency = counters.reduce((acc, curr) => acc + curr, 0) / 1000;
          this.eventEmitter.emit(PIPELINE_LATENCY_EVENT_NAME, totalLatency);
        },
      );
    }
  }

  private getInputIds(pipeline: Pipeline): string[] {
    const { inputIds, inputId } = pipeline;
    if (inputIds && inputIds.length) {
      return inputIds;
    }
    if (inputId) {
      return [inputId];
    }
    return [];
  }

  async startPipeline() {
    if (
      this._status === 'running' ||
      (this._pipelineProcess && !this._pipelineProcess.killed)
    ) {
      this.logger.warn('Pipeline is already running');
      throw new BadRequestException('Pipeline is already running');
    }

    if (this._status === 'stopping') {
      await wait(1000);
      return this.startPipeline();
    }

    const scailxEmbeddedBuildFolder = appConfig.SCAILX_EMBEDDED;
    if (!scailxEmbeddedBuildFolder) {
      throw new InternalServerErrorException('SCAILX_EMBEDDED is not set');
    }

    this.status = 'validating pipeline...';
    this.logger.info('validating pipeline...');
    try {
      await this.validatePipeline();
    } catch (error) {
      this.status = 'error';
      this._statusMessage = 'Pipeline is not valid';
      this.logger.warn('Pipeline is not valid');
      return;
    }

    this.status = 'building pipeline...';
    this.logger.info('building pipeline...');
    let pipelineString = '';
    try {
      const pipeline = await this.jsonService.readSettings<Pipeline>(PIPELINE_FILENAME);
      const { components } = pipeline;
      const inputIds = this.getInputIds(pipeline);
      pipelineString = this.buildPipeline(components, inputIds).join(' ');
      await this.setupCounters(components);
    } catch (error) {
      this.status = 'error';
      this._statusMessage = 'Error while building pipeline';
      this.logger.warn(`Error while building pipeline`);
      this.logger.info(error);
      return;
    }
    if (!pipelineString) {
      throw new InternalServerErrorException('Pipeline string is empty');
    }

    const pipelineFilePath = resolve(scailxEmbeddedBuildFolder, 'pipeline.txt');
    const countersFilePath = resolve(scailxEmbeddedBuildFolder, 'counters.txt');
    const pipelineFile = await Bun.file(pipelineFilePath);
    await pipelineFile.write(pipelineString);
    const launcherPath = resolve(scailxEmbeddedBuildFolder, 'usr', 'bin', 'launcher');

    try {
      this.status = 'launching gstreamer pipeline...';

      // this.logger.info(`Pipeline: ${pipelineString}`);
      this._pipelineProcess = Bun.spawn(
        [launcherPath, pipelineFilePath, countersFilePath],
        {
          cwd: scailxEmbeddedBuildFolder,
          stdout: 'pipe',
          stderr: 'pipe',
          env: process.env,
          onExit: (_proc, code, _signal, error) => {
            this.logger.info(`Pipeline process exited with code ${code}`);
            this.status = 'stopped';
            this._statusMessage = '';

            if (error || ![0, null, undefined].includes(code)) {
              this._statusMessage = `Exited with error`;
            }
            if (error) {
              this._gstreamerLogger.error(error.message);
            }
          },
        },
      );

      const processLauncherLogs = (log: string) => {
        if (log.includes('perf: perf0') || log.includes('baseparse')) return;
        if (log.includes('0x')) {
          log = log
            .split(/\s+/)
            .slice(4)
            .map((item) => item.trim())
            .filter((item) => !!item)
            .join(' ');
          this._gstreamerLogger.debug(log);
        } else if (
          log.toUpperCase().includes('WARN') ||
          log.toUpperCase().includes('W ')
        ) {
          this._gstreamerLogger.warn(log);
        } else if (log.toUpperCase().includes('ERROR')) {
          this._gstreamerLogger.error(log);
        } else if (log.toUpperCase().includes('MESSAGE')) {
          this._gstreamerLogger.info(log);
        } else if (log.toUpperCase().includes('INFO')) {
          this._gstreamerLogger.info(log);
        } else if (log.toUpperCase().includes('DEBUG')) {
          this._gstreamerLogger.debug(log);
        } else {
          this._gstreamerLogger.info(log);
        }
      };

      readStream(this._pipelineProcess.stdout, (data) => {
        const logs = data
          .split(os.EOL)
          .map((line) => line.trim())
          .filter((line) => !!line);
        for (let log of logs) {
          const fpsKey = '[FPS] ';
          const latencyKey = '[LATENCY] ';
          if (log.includes(fpsKey)) {
            const fpsSubStrIndex = log.indexOf(fpsKey) + fpsKey.length;
            const fpsString = log.slice(fpsSubStrIndex);
            const fps = parseFloat(fpsString);
            this.eventEmitter.emit(PIPELINE_FPS_EVENT_NAME, fps);
          } else if (log.includes(latencyKey)) {
            const latencySubStrIndex = log.indexOf(latencyKey) + latencyKey.length;
            const [elementId, latencyString] = log.slice(latencySubStrIndex).split(' ');
            const latency = parseInt(latencyString);
            this._latencyCounters$[elementId].next(latency);
          } else if (log.includes('status: ok')) {
            this.status = 'running';
            this._statusMessage = '';
          } else {
            processLauncherLogs(log);
          }
        }
      });
      readStream(this._pipelineProcess.stderr, (data) => {
        const logs = data
          .split(os.EOL)
          .map((line) => line.trim())
          .filter((line) => !!line);
        for (let log of logs) {
          processLauncherLogs(log);
        }
      });

      wait(2000).then(() => {
        if (
          this._status === 'launching gstreamer pipeline...' &&
          this._pipelineProcess &&
          !this._pipelineProcess.killed
        ) {
          this.status = 'running';
          this._statusMessage = '';
        }
      });
    } catch (error) {
      this.status = 'error';
      this._statusMessage = 'Error while starting pipeline';
      this.logger.warn(`Can't run pipeline:`);
      this.logger.error(error.message);
    }
  }

  async stopPipeline() {
    this.logger.info('Stopping pipeline...');
    this.status = 'stopping...';
    this._statusMessage = '';

    if (this._pipelineProcess !== null) {
      this._pipelineProcess.kill('SIGINT');
      await Promise.race([this._pipelineProcess.exited, wait(2000)]);
      if (!this._pipelineProcess.killed) {
        this._pipelineProcess.kill('SIGKILL');
        await this._pipelineProcess.exited;
      }
    }

    this._pipelineProcess = null;
    this.status = 'stopped';
    this._statusMessage = '';

    this._latencyCounters$ = {};
    if (this._latencyCounterSub) {
      this._latencyCounterSub.unsubscribe();
      this._latencyCounterSub = null;
    }
  }

  async restartPipeline(autoStart = true) {
    await this.stopPipeline();

    if (autoStart) {
      this.status = 'restarting';
      await wait(2000);
      await this.startPipeline();
    }
  }

  async validatePipeline() {
    const { components, inputIds } =
      await this.jsonService.readSettings<Pipeline>(PIPELINE_FILENAME);

    if (!components || !Object.keys(components).length) {
      throw new Error('Pipeline components are empty');
    }

    const inputComponents = components.filter((component) =>
      inputIds.includes(component.id),
    );
    if (
      !inputIds.length ||
      !inputComponents.length ||
      inputComponents.some((component) => component.data.category !== 'inputs')
    ) {
      throw new Error('Input component is not valid');
    }

    if (inputIds.length > 1) {
      throw new Error('Multiple input components are not supported');
    }

    const outputComponents = components.filter(
      (component) =>
        component.data.category === 'outputs' || component.data.type.includes('sink'),
    );

    if (!outputComponents.length) {
      throw new Error('Output component is missing');
    }
  }

  // TODO: better typing
  async getPipelineComponents(): Promise<PipelineComponentsDto> {
    this.logger.info('Reading pipeline from json file...');
    const pipeline = await this.jsonService.readSettings<Pipeline>(PIPELINE_FILENAME);
    // const components = Object.values(pipeline.components);
    return pipeline.components;
  }

  async setPipelineComponents(components: PipelineComponentsDto): Promise<void> {
    const inputIds = components
      .filter(
        (component) => component.data.category === 'inputs' && !component.parentId,
      )
      .map((component) => component.id);

    const pipelineComponentsChanges: Partial<Pipeline> = {
      components,
      inputIds: inputIds || [],
    };
    this.logger.info(
      `Setting new pipeline components: ${JSON.stringify(pipelineComponentsChanges)}`,
    );
    await this.jsonService.updateSettings(PIPELINE_FILENAME, pipelineComponentsChanges);
  }

  async exportPipeline(pipeline: Pipeline) {
    try {
      const { components } = pipeline;
      const inputIds = this.getInputIds(pipeline);
      const pipelineString = this.buildPipeline(components, inputIds)
        .join(' ')
        .replace(/bin\.\s\(\sname=\w+\s/g, '')
        .replace(/\s\)/g, '');
      return pipelineString;
    } catch (error) {
      throw new InternalServerErrorException('Error while exporting pipeline');
    }
  }

  async importPipeline(pipelineString: string): Promise<Pipeline> {
    const scailxEmbeddedBuildFolder = appConfig.SCAILX_EMBEDDED;
    if (!scailxEmbeddedBuildFolder) {
      const message =
        "SCAILX_EMBEDDED environment variable is not set, can't find parser";
      this.logger.warn(message);
      throw new InternalServerErrorException(message);
    }

    const dataFolder = appConfig.SCAILX_PORTAL_PROJECT_DATA;
    if (!dataFolder) {
      const message =
        "SCAILX_PORTAL_PROJECT_DATA environment variable is not set, can't read parsed pipeline";
      this.logger.warn(message);
      throw new InternalServerErrorException(message);
    }

    const parserPath = resolve(
      scailxEmbeddedBuildFolder,
      'usr',
      'bin',
      'parser',
      'parse.py',
    );

    const parsedPipelinePath = resolve(dataFolder, 'temp', 'parsed.json');

    try {
      await $`python3 ${parserPath} ${parsedPipelinePath} "${pipelineString}"`.quiet();
    } catch (error) {
      this.logger.error(`Error while parsing pipeline: ${error.message}`);
      if (error instanceof $.ShellError) {
        const errorMessage = error.stderr.toString();
        this.logger.error(errorMessage);
      }
      throw new InternalServerErrorException('Error while parsing pipeline');
    }

    const parsedPipelineComponents = (await Bun.file(
      parsedPipelinePath,
    ).json()) as PipelineComponentsDto;

    return {
      components: parsedPipelineComponents,
      inputIds: [],
      autoStart: false,
    };
  }
}
