import { Controller, Get, UseGuards } from '@nestjs/common';
import type { SDCardData } from '@scailx/shared';
import { JwtAuthGuard } from 'src/auth/guards';
import { HardwareService } from './hardware.service';

@UseGuards(JwtAuthGuard)
@Controller('hardware')
export class HardwareController {
  constructor(private readonly hardwareService: HardwareService) {}

  @Get('sd-card')
  async getSDCardPath(): Promise<SDCardData> {
    const sdCardData = await this.hardwareService.getSDCardStatus();
    return {
      device: sdCardData.device,
      mountPoint: sdCardData.mountPoint,
    };
  }

  @Get('hailo')
  async isHailoInstalled() {
    return this.hardwareService.isHailoInstalled();
  }
}
