import { OmitType } from '@nestjs/swagger';
import {
  IsBoolean,
  IsNotEmpty,
  IsOptional,
  IsString,
  MinLength,
} from 'class-validator';
import { CreateUserDto } from './create-user.dto';

export class PutManyUserDto extends OmitType(CreateUserDto, ['password']) {
  @IsNotEmpty()
  @IsString()
  id: string;

  @IsString()
  @IsNotEmpty()
  @MinLength(5)
  @IsOptional()
  password?: string;

  @IsBoolean()
  isNew: boolean;
}
