import { Injectable } from '@nestjs/common';
import { SCAILX_PORTAL_SETTINGS_FOLDER } from '@scailx/shared';
import { readFile, stat, writeFile } from 'node:fs/promises';
import { resolve } from 'node:path';
import { appConfig, createLogger } from 'src/utils';
import { type JsonSettings } from './types';

@Injectable()
export class JsonSettingsService {
  private readonly logger = createLogger('JsonSettingsService');

  async initSettings<T extends Record<string, unknown> | unknown[]>(
    name: string,
    defaultSettings: T,
  ): Promise<void> {
    const dataPath = appConfig.SCAILX_PORTAL_PROJECT_DATA;

    const filePath = resolve(dataPath, SCAILX_PORTAL_SETTINGS_FOLDER, `${name}.json`);
    const fileExists = await stat(filePath)
      .then((stats) => stats.isFile())
      .catch(() => false);
    if (!fileExists) {
      this.logger.warn(`JSON file ${name}.json doesn't exist, creating it`);
      await writeFile(filePath, JSON.stringify(defaultSettings, null, 2));
      return;
    }
    try {
      const fileContent = await Bun.file(filePath).text();
      JSON.parse(fileContent); // check if file is valid JSON
      return;
    } catch (error) {
      this.logger.warn(`Error checking JSON file ${name}.json, resetting to default`);
      this.logger.debug(error);
    }

    await writeFile(filePath, JSON.stringify(defaultSettings, null, 2));
  }

  async readSettings<T extends JsonSettings>(name: string): Promise<T> {
    const dataPath = appConfig.SCAILX_PORTAL_PROJECT_DATA;

    const filePath = resolve(dataPath, SCAILX_PORTAL_SETTINGS_FOLDER, `${name}.json`);
    const fileExists = await stat(filePath)
      .then((stats) => stats.isFile())
      .catch(() => false);
    if (!fileExists) {
      throw new Error(`File ${name}.json does not exist`);
    }
    const fileContent = await readFile(filePath, 'utf-8');
    try {
      return JSON.parse(fileContent) as T;
    } catch (error) {
      console.error(`Error parsing JSON file ${name}.json:`, error);
      throw new Error(`Error parsing JSON file ${name}.json: ${error.message}`);
    }
  }

  async writeSettings(name: string, settings: JsonSettings): Promise<void> {
    const dataPath = appConfig.SCAILX_PORTAL_PROJECT_DATA;

    const filePath = resolve(dataPath, SCAILX_PORTAL_SETTINGS_FOLDER, `${name}.json`);
    await writeFile(filePath, JSON.stringify(settings, null, 2));
  }

  async updateSettings<T extends JsonSettings>(
    name: string,
    settingsChanges: Partial<T>,
  ): Promise<void> {
    const currentSettings = await this.readSettings<T>(name);
    await this.writeSettings(name, Object.assign({}, currentSettings, settingsChanges));
  }
}
