import {
  Body,
  Controller,
  Get,
  NotFoundException,
  Put,
  Query,
  UseGuards,
} from '@nestjs/common';
import type { CameraDevice } from '@scailx/shared';
import { JwtAuthGuard } from 'src/auth/guards';
import { appConfig } from 'src/utils';
import { LocalCameraService } from './local-camera.service';
import type { CameraParamsDto } from './types';

@UseGuards(JwtAuthGuard)
@Controller('local-camera')
export class LocalCameraController {
  constructor(private readonly localCameraService: LocalCameraService) {}

  @Get('list')
  async getList() {
    if (appConfig.SCAILX_PORTAL_RUNNING_ON_PC) {
      return this.localCameraService.getV4l2CameraList();
    }

    try {
      return this.localCameraService.getCameraList();
    } catch (error) {
      return this.localCameraService.getV4l2CameraList();
    }
  }

  @Get('formats')
  async getFormats(@Query('device') device: CameraDevice) {
    try {
      return this.localCameraService.getFormats(device);
    } catch (error) {
      throw new NotFoundException(error.message);
    }
  }

  @Get('controls')
  async getControls(@Query('device') device: CameraDevice) {
    try {
      return this.localCameraService.getControls(device);
    } catch (error) {
      throw new NotFoundException(error.message);
    }
  }

  @Put('controls')
  async setControls(@Body() cameraParams: CameraParamsDto) {
    try {
      await this.localCameraService.setControls(cameraParams);
    } catch (error) {
      throw new NotFoundException(error.message);
    }
  }
}
