import {
  Controller,
  Delete,
  Get,
  HttpCode,
  HttpStatus,
  Param,
  ParseFilePipeBuilder,
  Put,
  Res,
  UploadedFiles,
  UseGuards,
  UseInterceptors,
} from '@nestjs/common';
import { FilesInterceptor } from '@nestjs/platform-express';
import {
  Role,
  SCAILX_PORTAL_MODELS_FOLDER,
  SCAILX_PORTAL_SCRIPTS_FOLDER,
  SCAILX_PORTAL_SD_CARD_FOLDER,
  SCAILX_PORTAL_TEXT_FILES_FOLDER,
  SCAILX_PORTAL_VIDEO_FOLDER,
} from '@scailx/shared';
import type { Response } from 'express';
import { JwtAuthGuard } from 'src/auth/guards';
import { FileExtensionValidator } from 'src/common/entities/FileExtensionValidator';
import { Roles } from 'src/common/roles/roles.decorator';
import { RolesGuard } from 'src/common/roles/roles.guard';
import { FilesService } from './files.service';

@UseGuards(JwtAuthGuard, RolesGuard)
@Controller('files')
export class FilesController {
  constructor(private readonly filesService: FilesService) {}

  @HttpCode(HttpStatus.OK)
  @Roles([Role.Admin, Role.PipelineOperator])
  @Get(`list/${SCAILX_PORTAL_MODELS_FOLDER}`)
  async getModelsList() {
    return this.filesService.getModelsList();
  }

  @HttpCode(HttpStatus.OK)
  @Roles([Role.Admin, Role.PipelineOperator])
  @Get(`list/${SCAILX_PORTAL_TEXT_FILES_FOLDER}`)
  async getTextFilesList() {
    return this.filesService.getTextFilesList();
  }

  @HttpCode(HttpStatus.OK)
  @Roles([Role.Admin, Role.PipelineOperator])
  @Get(`list/${SCAILX_PORTAL_VIDEO_FOLDER}`)
  async getLocalVideoList() {
    return this.filesService.getLocalVideoList();
  }

  @HttpCode(HttpStatus.OK)
  @Roles([Role.Admin, Role.PipelineOperator])
  @Get(`list/${SCAILX_PORTAL_SCRIPTS_FOLDER}`)
  async getScriptsList() {
    return this.filesService.getScriptsList();
  }
  @HttpCode(HttpStatus.OK)
  @Roles([Role.Admin, Role.PipelineOperator])
  @Get(`list/${SCAILX_PORTAL_SD_CARD_FOLDER}`)
  async getSDCardList() {
    return this.filesService.getSDCardList();
  }

  @HttpCode(HttpStatus.OK)
  @Roles([Role.Admin, Role.PipelineOperator])
  @Get(`${SCAILX_PORTAL_TEXT_FILES_FOLDER}/:filename`)
  async getTextFile(@Param('filename') filename: string, @Res() res: Response) {
    const textFilePath = await this.filesService.getTextFilepath(filename);
    res.download(textFilePath);
  }

  @HttpCode(HttpStatus.OK)
  @Roles([Role.Admin, Role.PipelineOperator])
  @Get(`${SCAILX_PORTAL_MODELS_FOLDER}/:filename`)
  async getModel(@Param('filename') filename: string, @Res() res: Response) {
    const modelPath = await this.filesService.getModelFilePath(filename);
    res.download(modelPath);
  }
  @HttpCode(HttpStatus.OK)
  @Roles([Role.Admin, Role.PipelineOperator])
  @Get(`${SCAILX_PORTAL_VIDEO_FOLDER}/:filename`)
  async getLocalVideo(@Param('filename') filename: string, @Res() res: Response) {
    const localVideoPath = await this.filesService.getLocalVideoFilePath(filename);
    res.download(localVideoPath);
  }

  @HttpCode(HttpStatus.OK)
  @Roles([Role.Admin, Role.PipelineOperator])
  @Get(`${SCAILX_PORTAL_SCRIPTS_FOLDER}/:filename`)
  async getScript(@Param('filename') filename: string, @Res() res: Response) {
    const scriptPath = await this.filesService.getScriptFilePath(filename);
    res.download(scriptPath);
  }

  @HttpCode(HttpStatus.OK)
  @Roles([Role.Admin, Role.PipelineOperator])
  @Get(`${SCAILX_PORTAL_SD_CARD_FOLDER}/:filename`)
  async getSDCardFile(@Param('filename') filename: string, @Res() res: Response) {
    const sdCardFilePath = await this.filesService.getSDCardFilePath(filename);
    res.download(sdCardFilePath);
  }

  @HttpCode(HttpStatus.OK)
  @Roles([Role.Admin])
  @UseInterceptors(FilesInterceptor(SCAILX_PORTAL_MODELS_FOLDER))
  @Put(SCAILX_PORTAL_MODELS_FOLDER)
  async uploadModel(
    @UploadedFiles(
      new ParseFilePipeBuilder()
        .addFileTypeValidator({
          fileType: 'application/octet-stream',
          skipMagicNumbersValidation: true,
        })
        .build({
          errorHttpStatusCode: HttpStatus.UNPROCESSABLE_ENTITY,
        }),
    )
    _models: Express.Multer.File[],
  ) {}

  @HttpCode(HttpStatus.OK)
  @Roles([Role.Admin])
  @UseInterceptors(FilesInterceptor(SCAILX_PORTAL_TEXT_FILES_FOLDER))
  @Put(SCAILX_PORTAL_TEXT_FILES_FOLDER)
  async uploadTextFile(
    @UploadedFiles(
      new ParseFilePipeBuilder()
        .addFileTypeValidator({
          fileType: /text\/plain|application\/json/,
          skipMagicNumbersValidation: true,
        })
        .addValidator(
          new FileExtensionValidator({
            extensions: ['.txt', '.json'],
          }),
        )
        .build({
          errorHttpStatusCode: HttpStatus.UNPROCESSABLE_ENTITY,
        }),
    )
    _labels: Express.Multer.File,
  ) {}

  @HttpCode(HttpStatus.OK)
  @Roles([Role.Admin])
  @Put(SCAILX_PORTAL_VIDEO_FOLDER)
  @UseInterceptors(FilesInterceptor(SCAILX_PORTAL_VIDEO_FOLDER))
  async uploadVideo(
    @UploadedFiles(
      new ParseFilePipeBuilder()
        .addFileTypeValidator({
          fileType: 'mp4',
          skipMagicNumbersValidation: true,
        })
        .build({
          errorHttpStatusCode: HttpStatus.UNPROCESSABLE_ENTITY,
        }),
    )
    _videos: Express.Multer.File[],
  ) {}

  @HttpCode(HttpStatus.OK)
  @Roles([Role.Admin])
  @UseInterceptors(FilesInterceptor(SCAILX_PORTAL_SCRIPTS_FOLDER))
  @Put(SCAILX_PORTAL_SCRIPTS_FOLDER)
  async uploadScript(
    @UploadedFiles(
      new ParseFilePipeBuilder()
        .addFileTypeValidator({
          fileType: /text\/plain|text\/x-python/,
          skipMagicNumbersValidation: true,
        })
        .addValidator(
          new FileExtensionValidator({
            extensions: ['.py'],
          }),
        )
        .build({
          errorHttpStatusCode: HttpStatus.UNPROCESSABLE_ENTITY,
        }),
    )
    _scripts: Express.Multer.File,
  ) {}

  @HttpCode(HttpStatus.OK)
  @Roles([Role.Admin])
  @UseInterceptors(FilesInterceptor(SCAILX_PORTAL_SD_CARD_FOLDER))
  @Put(SCAILX_PORTAL_SD_CARD_FOLDER)
  async uploadSDCardFile(
    @UploadedFiles()
    _files: Express.Multer.File[],
  ) {}

  @HttpCode(HttpStatus.NO_CONTENT)
  @Delete(`${SCAILX_PORTAL_MODELS_FOLDER}/:filename`)
  @Roles([Role.Admin])
  async deleteModel(@Param('filename') filename: string) {
    return this.filesService.deleteModel(filename);
  }

  @HttpCode(HttpStatus.NO_CONTENT)
  @Roles([Role.Admin])
  @Delete(`${SCAILX_PORTAL_TEXT_FILES_FOLDER}/:filename`)
  async deleteTextFile(@Param('filename') filename: string) {
    return this.filesService.deleteTextFile(filename);
  }

  @HttpCode(HttpStatus.NO_CONTENT)
  @Roles([Role.Admin])
  @Delete(`${SCAILX_PORTAL_VIDEO_FOLDER}/:filename`)
  async deleteLocalVideo(@Param('filename') filename: string) {
    return this.filesService.deleteLocalVideo(filename);
  }

  @HttpCode(HttpStatus.NO_CONTENT)
  @Roles([Role.Admin])
  @Delete(`${SCAILX_PORTAL_SCRIPTS_FOLDER}/:filename`)
  async deleteScript(@Param('filename') filename: string) {
    return this.filesService.deleteScript(filename);
  }
}
