import { Injectable } from '@nestjs/common';
import type { ReverseProxyConfig } from '@scailx/shared';
import { JsonSettingsService } from 'src/common/json/json.service';

@Injectable()
export class ReverseProxyService {
  constructor(private readonly jsonSettingsService: JsonSettingsService) {}

  getReverseProxyConfig() {
    return this.jsonSettingsService.readSettings<ReverseProxyConfig[]>(
      'reverse-proxy.config',
    );
  }
}
