import {
  Injectable,
  InternalServerErrorException,
  NotFoundException,
} from '@nestjs/common';
import {
  SCAILX_PORTAL_MODELS_FOLDER,
  SCAILX_PORTAL_SCRIPTS_FOLDER,
  SCAILX_PORTAL_TEXT_FILES_FOLDER,
  SCAILX_PORTAL_VIDEO_FOLDER,
} from '@scailx/shared';
import { readdir } from 'node:fs/promises';
import { resolve } from 'path';
import { appConfig, asyncFilter, createLogger, getSDCardStatus } from 'src/utils';

@Injectable()
export class FilesService {
  private readonly logger = createLogger('FilesService');

  async cleanDataFolder(folder: string, filetype: string, exception: string) {
    const commonDataFolder = appConfig.SCAILX_PORTAL_PROJECT_DATA;
    const dataFolder = resolve(commonDataFolder, folder);
    const dataFolderFiles = await readdir(dataFolder);
    for (const file of dataFolderFiles) {
      // cleaning all other files of the same type
      if (file !== exception && file.endsWith(filetype)) {
        await Bun.file(resolve(dataFolder, file))
          .delete()
          .catch(() => {});
      }
    }
  }

  async getTextFilepath(filename: string): Promise<string> {
    return this.getFilePath(SCAILX_PORTAL_TEXT_FILES_FOLDER, filename);
  }

  async getModelFilePath(filename: string): Promise<string> {
    return this.getFilePath(SCAILX_PORTAL_MODELS_FOLDER, filename);
  }

  async getLocalVideoFilePath(filename: string): Promise<string> {
    return this.getFilePath(SCAILX_PORTAL_VIDEO_FOLDER, filename);
  }

  async getScriptFilePath(filename: string): Promise<string> {
    return this.getFilePath(SCAILX_PORTAL_SCRIPTS_FOLDER, filename);
  }

  private async getSDCardFolderPath(): Promise<string> {
    try {
      const { mountPoint } = await getSDCardStatus();
      return mountPoint;
    } catch (error) {
      if (error instanceof Error) {
        this.logger.warn(error.message);
      }
      this.logger.error(error);
      throw new InternalServerErrorException("Can't read SDCard path");
    }
  }

  async getSDCardFilePath(filename: string): Promise<string> {
    const mountPoint = await this.getSDCardFolderPath();
    const filePath = resolve(mountPoint, filename);
    const fileExists = await Bun.file(filePath).exists();
    if (!fileExists) {
      const errorMessage = `file ${filename} not found on SDCard`;
      this.logger.error(errorMessage);
      throw new NotFoundException(errorMessage);
    }
    return filePath;
  }

  async getFilePath(subfolder: string, filename: string): Promise<string> {
    const commonDataFolder = appConfig.SCAILX_PORTAL_PROJECT_DATA;
    const filePath = resolve(commonDataFolder, subfolder, filename);
    const fileExists = await Bun.file(filePath).exists();
    if (!fileExists) {
      const errorMessage = `file ${filename} not found in ${subfolder}`;
      this.logger.error(errorMessage);
      throw new NotFoundException(errorMessage);
    }
    return filePath;
  }

  async getFileList(subfolder: string): Promise<string[]> {
    const commonDataFolder = appConfig.SCAILX_PORTAL_PROJECT_DATA;
    const filePath = resolve(commonDataFolder, subfolder);
    const fileList = await readdir(filePath);
    return fileList.map((file) => resolve(commonDataFolder, subfolder, file));
  }

  async isModelFile(filePath: string): Promise<boolean> {
    const file = await Bun.file(filePath);
    return file.type.includes('application/octet-stream');
  }

  async isTextFile(filePath: string): Promise<boolean> {
    const file = await Bun.file(filePath);
    return file.type.includes('text/plain') || file.name?.endsWith('.txt');
  }

  async isJsonFile(filePath: string): Promise<boolean> {
    const file = await Bun.file(filePath);
    return file.type.includes('application/json') && file.name?.endsWith('.json');
  }

  async isLocalVideoFile(filePath: string): Promise<boolean> {
    const file = await Bun.file(filePath);
    return file.type.includes('video/mp4');
  }

  async isScriptFile(filePath: string): Promise<boolean> {
    const file = await Bun.file(filePath, { type: 'text/x-python' });
    return file.name?.endsWith('.py');
  }

  async getModelsList(): Promise<string[]> {
    return await asyncFilter(
      await this.getFileList(SCAILX_PORTAL_MODELS_FOLDER),
      async (path) => !path.endsWith('.gitkeep') && (await this.isModelFile(path)),
    );
  }

  async getTextFilesList(): Promise<string[]> {
    return await asyncFilter(
      await this.getFileList(SCAILX_PORTAL_TEXT_FILES_FOLDER),
      async (path) =>
        !path.endsWith('.gitkeep') &&
        ((await this.isTextFile(path)) || (await this.isJsonFile(path))),
    );
  }

  async getLocalVideoList(): Promise<string[]> {
    return await asyncFilter(
      await this.getFileList(SCAILX_PORTAL_VIDEO_FOLDER),
      async (path) => !path.endsWith('.gitkeep') && (await this.isLocalVideoFile(path)),
    );
  }

  async getScriptsList(): Promise<string[]> {
    return await asyncFilter(
      await this.getFileList(SCAILX_PORTAL_SCRIPTS_FOLDER),
      async (path) => !path.endsWith('.gitkeep') && (await this.isScriptFile(path)),
    );
  }
  async getSDCardList(): Promise<string[]> {
    const sdCardFolderPath = await this.getSDCardFolderPath();
    const fileList = await readdir(sdCardFolderPath);
    return fileList.map((file) => resolve(sdCardFolderPath, file));
  }

  async deleteFile(subfolder: string, filename: string): Promise<void> {
    const filePath = resolve(appConfig.SCAILX_PORTAL_PROJECT_DATA, subfolder, filename);
    const file = await Bun.file(filePath);
    if (!file.exists()) {
      const errorMessage = `File ${filename} not found in ${subfolder}`;
      this.logger.error(errorMessage);
      throw new NotFoundException(errorMessage);
    }
    this.logger.info(`Deleting file ${filename} from ${subfolder}`);
    await file.delete().catch(() => {});
  }

  async deleteModel(filename: string): Promise<void> {
    await this.deleteFile(SCAILX_PORTAL_MODELS_FOLDER, filename);
  }

  async deleteTextFile(filename: string): Promise<void> {
    await this.deleteFile(SCAILX_PORTAL_TEXT_FILES_FOLDER, filename);
  }

  async deleteLocalVideo(filename: string): Promise<void> {
    await this.deleteFile(SCAILX_PORTAL_VIDEO_FOLDER, filename);
  }

  async deleteScript(filename: string): Promise<void> {
    await this.deleteFile(SCAILX_PORTAL_SCRIPTS_FOLDER, filename);
  }

  async deleteSDCardFile(filename: string): Promise<void> {
    const sdCardFolderPath = await this.getSDCardFolderPath();
    const filePath = resolve(sdCardFolderPath, filename);
    const file = await Bun.file(filePath);
    if (!file.exists()) {
      const errorMessage = `File ${filename} not found on SDCard`;
      this.logger.error(errorMessage);
      throw new NotFoundException(errorMessage);
    }
    this.logger.info(`Deleting file ${filename} from SDCard`);
    await file.delete().catch(() => {});
  }
}
