import {
  BadRequestException,
  ConflictException,
  Injectable,
  InternalServerErrorException,
  NotFoundException,
  type OnModuleInit,
  UnauthorizedException,
} from '@nestjs/common';
import { Role, type UserBase } from '@scailx/shared';
import _ from 'lodash';
import { JsonSettingsService } from 'src/common/json/json.service';
import { appConfig, createLogger, USERS_FILENAME } from 'src/utils';
import { ChangePasswordDto, CreateUserDto, PutManyUserDto, UpdateUserDto } from './dto';
import type { User } from './entities';

@Injectable()
export class UsersService implements OnModuleInit {
  private readonly logger = createLogger('UsersService');
  constructor(private readonly jsonService: JsonSettingsService) {}

  async onModuleInit() {
    await this.jsonService.initSettings(USERS_FILENAME, []);
    const users = await this.getUsers();
    const newUsers = [...users];

    if (!users.length) {
      const seedAdminUsername = appConfig.SEED_ADMIN_USERNAME;
      const seedAdminPassword = appConfig.SEED_ADMIN_PASSWORD;
      if (!seedAdminUsername || !seedAdminPassword) {
        throw new Error('SEED_ADMIN_USERNAME and SEED_ADMIN_PASSWORD must be set');
      }
      const hashedPassword = await this.hashPassword(seedAdminPassword);
      newUsers.push({
        username: seedAdminUsername,
        hashedPassword,
        id: crypto.randomUUID(),
        roles: [Role.Admin],
      });
    }
    await this.setUsers(newUsers);
  }

  async getUsers(): Promise<User[]> {
    try {
      const users = await this.jsonService.readSettings<User[]>(USERS_FILENAME);
      return users;
    } catch (error) {
      this.logger.debug(error);
      throw new InternalServerErrorException('Failed to get users');
    }
  }

  async setUsers(users: User[]): Promise<void> {
    try {
      await this.jsonService.writeSettings(USERS_FILENAME, users);
    } catch (error) {
      this.logger.debug(error);
      throw new InternalServerErrorException('Failed to set users');
    }
  }

  async hashPassword(password: string): Promise<string> {
    return await Bun.password.hash(password, {
      algorithm: 'argon2id', // "argon2id" | "argon2i" | "argon2d"
      memoryCost: 4, // memory usage in kibibytes
      timeCost: 3, // the number of iterations
    });
  }

  async createMany(createUserDtos: CreateUserDto[]): Promise<UserBase[]> {
    const users = await this.getUsers();
    const newUsers: User[] = [];

    for (const createUserDto of createUserDtos) {
      if (users.some((user) => user.username === createUserDto.username)) {
        throw new ConflictException('User with this username already exists');
      }
      const { username, password, roles } = createUserDto;

      const newUser = {
        id: crypto.randomUUID(),
        hashedPassword: await this.hashPassword(password),
        username,
        roles,
        refreshToken: '',
      };
      newUsers.push(newUser);
    }
    const updatedUsers = [...users, ...newUsers];

    this.setUsers(updatedUsers);

    return updatedUsers.map((user) => this.toOutput(user));
  }

  async createOrUpdateManyByUsername(
    putManyUsersDto: PutManyUserDto[],
  ): Promise<UserBase[]> {
    const users = await this.getUsers();
    const newUsers: User[] = [];
    const updatedUsers: User[] = [];
    for (const user of putManyUsersDto) {
      const { password, username, roles, id } = user;
      if (!username) {
        throw new BadRequestException('Username is required');
      }

      const existing = users.find((user) => user.id === id);
      if (!existing) {
        if (!password || !roles || roles.length === 0) {
          throw new BadRequestException(
            'Password and roles are required for new users',
          );
        }

        newUsers.push({
          id: crypto.randomUUID(),
          username,
          roles,
          hashedPassword: await this.hashPassword(password),
        });
      } else {
        const updatedUser: User = {
          ...existing,
          username,
          roles: roles.length > 0 ? roles : existing.roles,
          hashedPassword: password
            ? await this.hashPassword(password)
            : existing.hashedPassword,
        };

        updatedUsers.push(updatedUser);
      }
    }

    const resultUsers = [...newUsers, ...updatedUsers];
    this.setUsers(resultUsers);
    return resultUsers.map((user) => this.toOutput(user));
  }

  async findAll(): Promise<UserBase[]> {
    const users = await this.getUsers();
    return users.map((user) => this.toOutput(user));
  }

  async findOne(id: string): Promise<UserBase> {
    const users = await this.getUsers();
    const user = users.find((user) => user.id === id);
    if (!user) {
      throw new NotFoundException('User not found');
    }
    return this.toOutput(user);
  }

  async updateOneById(id: string, updateUserDto: UpdateUserDto): Promise<UserBase> {
    const users = await this.getUsers();
    const user = users.find((user) => user.id === id);
    if (!user) {
      throw new NotFoundException('User not found');
    }

    const { password, roles, username } = updateUserDto;

    const isLastAdmin = await this.isLastAdmin(id);
    if (isLastAdmin && !roles?.includes(Role.Admin)) {
      throw new BadRequestException('Cannot remove last admin role');
    }

    const updatedUser: User = {
      ...user,
      username: username ?? user.username,
      roles: roles && roles.length > 0 ? roles : user.roles,
      hashedPassword: password
        ? await this.hashPassword(password)
        : user.hashedPassword,
    };

    const newUsers = users.map((user) => {
      if (user.id === id) {
        return updatedUser;
      }
      return user;
    });

    this.setUsers(newUsers);
    return this.toOutput(updatedUser);
  }

  async changePasswordById(
    id: string,
    changePasswordDto: ChangePasswordDto,
  ): Promise<UserBase> {
    const users = await this.getUsers();
    const user = users.find((user) => user.id === id);
    if (!user) {
      throw new NotFoundException('User not found');
    }

    const { newPassword, password } = changePasswordDto;

    if (!newPassword) {
      throw new BadRequestException('New password is required');
    }

    if (user.id !== id) {
      throw new BadRequestException('Cannot change password for another user');
    }

    const isValid = await Bun.password.verify(String(password), user.hashedPassword);
    if (!isValid) throw new UnauthorizedException('Old password is incorrect');

    const updatedUser: User = {
      ...user,
      hashedPassword: await this.hashPassword(newPassword),
    };

    const newUsers = users.map((user) => {
      if (user.id === id) {
        return updatedUser;
      }
      return user;
    });

    this.setUsers(newUsers);
    return this.toOutput(updatedUser);
  }

  async removeOneById(id: string, currentUserId: string): Promise<null | UserBase> {
    if (id === currentUserId) {
      throw new BadRequestException('Cannot delete the user currently logged in');
    }

    const users = await this.getUsers();
    const user = users.find((user) => user.id === id);
    if (!user) {
      return null;
    }

    const isLastAdmin = await this.isLastAdmin(id);
    if (users.length === 1 || isLastAdmin) {
      throw new BadRequestException('User cannot be deleted');
    }

    const newUsers = users.filter((user) => user.id !== id);
    this.setUsers(newUsers);
    return this.toOutput(user);
  }

  async removeManyByUsername(
    usernames: string[],
    currentUsername: string,
  ): Promise<UserBase[]> {
    const users = await this.getUsers();
    const newUsers = users.filter((user) => {
      if (user.username === currentUsername) {
        throw new BadRequestException('Cannot delete the user currently logged in');
      }
      return !usernames.includes(user.username);
    });

    const deletedUsers = users.filter((user) => usernames.includes(user.username));
    this.setUsers(newUsers);
    return deletedUsers.map((user) => this.toOutput(user));
  }

  toOutput(user: User): UserBase {
    return _.pick(user, 'id', 'username', 'roles');
  }

  async isLastAdmin(id: string): Promise<boolean> {
    const users = await this.getUsers();
    const admins = users.filter((user) => user.roles.includes(Role.Admin));
    if (admins.length === 0) {
      throw new InternalServerErrorException('No admins found');
    }
    return admins.length === 1 && admins[0].id === id;
  }
}
