import {
  Body,
  Controller,
  DefaultValuePipe,
  Get,
  HttpException,
  HttpStatus,
  ParseBoolPipe,
  Post,
  Put,
  Query,
  UseGuards,
} from '@nestjs/common';
import type {
  Pipeline,
  PipelineComponentsDto,
  PipelineStringExportImportDto,
} from '@scailx/shared';
import { Role } from '@scailx/shared';
import { connect } from 'mqtt';
import { JwtAuthGuard } from 'src/auth/guards';
import { Roles } from 'src/common/roles/roles.decorator';
import { RolesGuard } from 'src/common/roles/roles.guard';
import { PipelineService } from './pipeline.service';
import type { MQTTSettings } from './types';

@UseGuards(JwtAuthGuard, RolesGuard)
@Controller('pipeline')
export class PipelineController {
  constructor(private readonly pipelineService: PipelineService) {}

  @Roles([Role.Admin, Role.PipelineOperator])
  @Get()
  async getComponents(): Promise<PipelineComponentsDto> {
    const components = await this.pipelineService.getPipelineComponents();
    return components;
  }

  @Roles([Role.Admin, Role.PipelineOperator, Role.User])
  @Get('status')
  getStatus() {
    const { status, message, error } = this.pipelineService.getStatus();
    return {
      status,
      message,
      error,
      isError: status === 'error',
      isPending: status.includes('launching') || status === 'restarting',
    };
  }

  @Roles([Role.Admin, Role.PipelineOperator, Role.User])
  @Put('start')
  startPipeline() {
    this.pipelineService.startPipeline();
  }

  @Roles([Role.Admin, Role.PipelineOperator, Role.User])
  @Put('stop')
  stopPipeline() {
    this.pipelineService.stopPipeline();
  }

  @Roles([Role.Admin, Role.PipelineOperator, Role.User])
  @Put('restart')
  restartPipeline() {
    this.pipelineService.restartPipeline();
  }

  // TODO: add data validation, errors processing & status messages
  @Roles([Role.Admin, Role.PipelineOperator])
  @Put()
  async setComponents(
    @Body() components: PipelineComponentsDto,
    @Query('autoStart', new DefaultValuePipe(false), ParseBoolPipe) autoStart: boolean,
  ): Promise<void> {
    await this.pipelineService.setPipelineComponents(components);
    await this.pipelineService.restartPipeline(autoStart);
  }

  @Roles([Role.Admin, Role.PipelineOperator])
  @Get('mqtt/test')
  async testMqtt(@Query() mqttParams: MQTTSettings): Promise<void> {
    let success = false;
    const { link, port, topic, qosLevel } = mqttParams;
    const url = link.startsWith('mqtt://') ? link : `mqtt://${link}`;
    const client = connect(url, { port, connectTimeout: 5000 });
    client.on('connect', () => {
      client.publish(
        topic,
        'test message',
        {
          qos: qosLevel,
        },
        (err) => {
          if (success) {
            return;
          }
          if (err) {
            throw new HttpException(
              'Cant publish message to provided topic',
              HttpStatus.INTERNAL_SERVER_ERROR,
            );
          }
          client.end();
        },
      );
    });
    client.on('error', () => {
      if (!success) {
        throw new HttpException(
          'Cant connect to provided MQTT broker',
          HttpStatus.INTERNAL_SERVER_ERROR,
        );
      }
      client.end();
    });
  }

  @Roles([Role.Admin, Role.PipelineOperator])
  @Post('export')
  async exportPipeline(
    @Body() pipeline: Pipeline,
  ): Promise<PipelineStringExportImportDto> {
    const pipelineStr = await this.pipelineService.exportPipeline(pipeline);
    return {
      pipeline: pipelineStr,
    };
  }

  @Roles([Role.Admin, Role.PipelineOperator])
  @Put('import')
  async importPipeline(@Body() body: PipelineStringExportImportDto): Promise<Pipeline> {
    const parsedPipeline = await this.pipelineService.importPipeline(body.pipeline);
    return parsedPipeline;
  }
}
