import { Injectable, InternalServerErrorException } from '@nestjs/common';
import { type SDCardData } from '@scailx/shared';
import { createLogger, getSDCardStatus, isHailoAccInstalled } from 'src/utils';

@Injectable()
export class HardwareService {
  private readonly logger = createLogger('HardwareService');

  getSDCardStatus(): Promise<SDCardData> {
    try {
      return getSDCardStatus();
    } catch (error) {
      if (error instanceof Error) {
        this.logger.warn(error.message);
      }
      this.logger.error(error);
      throw new InternalServerErrorException("Can't read SDCard path");
    }
  }

  async isHailoInstalled(): Promise<{ hailo: boolean }> {
    try {
      const isHailoInstalled = await isHailoAccInstalled();
      return {
        hailo: isHailoInstalled,
      };
    } catch (error) {
      this.logger.warn("Can't read Hailo status");
      this.logger.error(error);
      return { hailo: false };
    }
  }
}
