import { Injectable, type OnModuleDestroy, type OnModuleInit } from '@nestjs/common';
import type { JournalctlLogEntry, LogEntry } from '@scailx/shared';

import { spawn, type Subprocess } from 'bun';
import { pick } from 'lodash';
import { readdir } from 'node:fs/promises';
import * as os from 'node:os';
import { resolve } from 'node:path';
import { wait } from 'src/common/utils';
import { createLogger, getLoggerPath, readStream } from 'src/utils';

@Injectable()
export class LogsService implements OnModuleInit, OnModuleDestroy {
  private readonly logger = createLogger('LogsService');
  private kernelLogsProcess: Subprocess;

  onModuleInit() {
    const kernelLogger = createLogger('Kernel', 'kernel');
    this.kernelLogsProcess = spawn(['journalctl', '-kf', '--no-pager', '-o', 'json']);
    const logsProcessor = () => {
      let jsonLogChunk = '';
      return (data) => {
        const logsJson = data
          .split(/(?=\{)\r*\n?/)
          .map((line) => line.trim())
          .filter((line) => line.length > 0);
        for (let log of logsJson) {
          if (!log.endsWith('}')) {
            jsonLogChunk += log;
            continue;
          }
          if (!log.startsWith('{')) {
            log = jsonLogChunk + log;
            jsonLogChunk = '';
          }
          let rawLogMessage: JournalctlLogEntry;
          try {
            rawLogMessage = JSON.parse(log) as JournalctlLogEntry;
          } catch (error) {
            this.logger.warn('Error while parsing log message:');
            this.logger.debug(log);
            continue;
          }

          const logMessage = pick(rawLogMessage, [
            '__REALTIME_TIMESTAMP',
            'MESSAGE',
            'PRIORITY',
          ]);
          switch (logMessage.PRIORITY) {
            case '0':
            case '1':
            case '2':
            case '3':
              kernelLogger.error(logMessage.MESSAGE);
              break;
            case '4':
              kernelLogger.warn(logMessage.MESSAGE);
              break;
            case '5':
            case '6':
              kernelLogger.info(logMessage.MESSAGE);
              break;
            case '7':
              kernelLogger.debug(logMessage.MESSAGE);
              break;
            default:
              kernelLogger.info(logMessage.MESSAGE);
              break;
          }
        }
      };
    };
    readStream(this.kernelLogsProcess.stdout, logsProcessor());
    readStream(this.kernelLogsProcess.stderr, (data) => {
      kernelLogger.error(data);
    });
  }

  async onModuleDestroy() {
    if (!this.kernelLogsProcess) return;
    this.kernelLogsProcess.kill('SIGINT');
    await Promise.race([this.kernelLogsProcess.exited, wait(1000)]);
    this.kernelLogsProcess = null;
  }

  async getLogsList(): Promise<string[]> {
    const logsFolderPath = getLoggerPath();
    const logFiles = await readdir(logsFolderPath);
    return logFiles.filter(
      (file) => file.startsWith('server') && file.includes('.log'),
    );
  }

  async getLogs(filename: string): Promise<LogEntry[]> {
    const date = filename.slice(7, filename.indexOf('.log'));
    const part = filename.endsWith('.log') ? '' : filename.split('.').pop();
    this.logger.info(
      `Getting logs for date ${date}` + (part ? `, part ${+part + 1}` : ''),
    );
    const logsPath = resolve(getLoggerPath(), filename);
    let logs = [];
    try {
      logs = (await Bun.file(logsPath).text())
        .split(os.EOL)
        .map((line) => line.trim())
        .filter((line) => line.length > 0)
        .map((line) => JSON.parse(line) as LogEntry);
    } catch (error) {
      this.logger.warn('No logs found for date ' + date);
    }
    return logs;
  }
}
