import { Controller, Get, Param, UseGuards } from '@nestjs/common';
import type { LogEntry } from '@scailx/shared';
import { JwtAuthGuard } from 'src/auth/guards';
import { LogsService } from './logs.service';

@UseGuards(JwtAuthGuard)
@Controller('logs')
export class LogsController {
  constructor(private readonly logsService: LogsService) {}

  @Get('list')
  async getLogsList(): Promise<string[]> {
    const list = await this.logsService.getLogsList();
    return list;
  }

  @Get(':filename')
  async getLogByFilename(@Param('filename') filename: string): Promise<LogEntry[]> {
    const logs = await this.logsService.getLogs(filename);
    return logs;
  }
}
