import { Injectable } from '@nestjs/common';
import { PIPELINE_STREAM_NAME } from '@scailx/shared';
import _ from 'lodash';
import { appConfig, createLogger } from 'src/utils';
import { parse, stringify } from 'yaml';

@Injectable()
export class Go2rtcService {
  private readonly logger = createLogger('Go2rtcService');

  async getGo2RtcConfig() {
    const go2rtcPort = appConfig.GO2RTC_PORT;
    const go2rtcSettings = await fetch(
      `http://127.0.0.1:${go2rtcPort}/api/config`,
    ).then((res) => res.text());
    
    let config: Record<string, any>

    try {
      config = parse(go2rtcSettings);
    } catch (error) {
      this.logger.error(`Failed to parse go2rtc settings: ${error}`);
      config = {};
    }

    return config;
  }

  async configureGo2Rtc() {
    const go2rtcPort = appConfig.GO2RTC_PORT;
    const currentConfig = await this.getGo2RtcConfig();
    const modules = currentConfig?.modules || [];

    const newConfig = {
      ...currentConfig,
      modules: _.uniq([...modules, 'api', 'rtsp', 'hls']),
      streams: {
        ...(currentConfig?.streams || {}),
        [PIPELINE_STREAM_NAME]: 'tcp://127.0.0.1:4953',
      },
      api: {
        ...(currentConfig?.api || {}),
        origin: '*',
      },
    };
    this.logger.info(`Configuring go2rtc: ${JSON.stringify(newConfig)}`);
    try {
      const response = await fetch(`http://127.0.0.1:${go2rtcPort}/api/config`, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/yaml',
        },
        body: stringify(newConfig),
      });
      if (!response.ok) {
        throw new Error(
          `Failed to configure go2RTC via http API: ${response.status} ${response.statusText}`,
        );
      }
    } catch (error) {
      this.logger.error(`Failed to configure go2RTC via http API: ${error}`);
      return;
    }

    this.logger.info('go2RTC modules configured');

    await fetch('http://127.0.0.1:1984/api/restart', { method: 'POST' });
    this.logger.info('go2RTC restarted');
  }
}
