import { Injectable, InternalServerErrorException, NotFoundException, type OnModuleInit } from '@nestjs/common';
import type { WifiNetwork } from '@scailx/shared';
import { $ } from 'bun';
import { filter, firstValueFrom, map, Observable, of, skipWhile, take, timeout } from 'rxjs';
import { DbusService } from 'src/common/dbus/dbus.service';
import { DbusMethods, type DbusVariant, Signals } from 'src/common/dbus/types';
import { createLogger } from 'src/utils';
import { type PropertiesChangedEvent, WifiMethods } from 'src/wifi/types';

@Injectable()
export class WifiService implements OnModuleInit {
  private readonly logger = createLogger('WifiService');
  private readonly IWD_SERVICE = 'net.connman.iwd';
  private readonly IWD_STATION_INTERFACE = 'net.connman.iwd.Station';
  private readonly IWD_NETWORK_INTERFACE = 'net.connman.iwd.Network';
  private readonly IWD_DEVICE_INTERFACE = 'net.connman.iwd.Device';
  private readonly DBUS_PROPERTIES_INTERFACE = 'org.freedesktop.DBus.Properties';
  private readonly DBUS_OBJECT_MANAGER_INTERFACE = 'org.freedesktop.DBus.ObjectManager';
  private readonly IWD_KNOWN_INTERFACE = 'net.connman.iwd.KnownNetwork';

  private stationScanningProp$?: Observable<boolean>;

  constructor(private readonly dbusService: DbusService) {}

  async onModuleInit() {

    try {
      await this.subscribeToStationScanningStatus();
      this.logger.info('WifiService initialized'); 
    } catch (err) {
      this.logger.error(`Failed to initialize WifiService: ${err.message}`);
    }
  }

  private async getIwdManagedObjects(): Promise<Record<string, any>> {
    try {
      return this.dbusService.callMethod<Record<string, any>>({
        serviceName: this.IWD_SERVICE,
        objectPath: '/',
        interfaceName: this.DBUS_OBJECT_MANAGER_INTERFACE,
        methodName: DbusMethods.GET_MANAGED_OBJECTS,
        methodArgs: [],
      });
    } catch (error) {
      throw new InternalServerErrorException(`Failed to get iwd managed objects: ${error.message}`);
    }
  }

  /**
   * Finds the first available wireless station
   */
  private async getStation(): Promise<[string, Record<string, any>]> {
    const managedObjects = await this.getIwdManagedObjects();

    const path = Object.keys(managedObjects).find((p) =>
      managedObjects[p].hasOwnProperty(this.IWD_STATION_INTERFACE)
    );
    if (!path) throw new NotFoundException('No wireless station device found.');
    return [path, managedObjects[path]];
  }

  
  private async getStationPath(): Promise<string> {
    const [path] = await this.getStation();
    return path;
  } 

  async getWifiInterfaceName(): Promise<string | null> {
    try {
      const [_, station] = await this.getStation();
      const deviceProps = station[this.IWD_DEVICE_INTERFACE];
      return deviceProps?.Name?.value || null;
    } catch (error) {
      this.logger.error(`Failed to retrieve wifi device name: ${error.message}`);
      return null;
    }
  }

  /**
   * Decodes the hex SSID from the iwd object path and converts mBm to Quality
   */
  private formatNetwork(path: string, signalStrength: number): Omit<WifiNetwork, 'isKnown' | 'isConnected'> {
    const pathParts = path.split('/');
    const rawSegment = pathParts[pathParts.length - 1]; // e.g., "5a54455f6e6577_psk"

    // 1. Separate the Hex SSID from the Security Type
    const lastUnderscore = rawSegment.lastIndexOf('_');
    const hexSsid = rawSegment.substring(0, lastUnderscore);
    const security = rawSegment.substring(lastUnderscore + 1);

    // 2. Decode Hex to UTF-8 String
    const name = Buffer.from(hexSsid, 'hex').toString('utf8');
    // Convert mBm to dBm, then to 0-100% quality
    const dbm = signalStrength / 100;
    const quality = Math.min(Math.max(2 * (dbm + 100), 0), 100);

    return {
      ssid: name,
      security,
      quality: Math.round(quality),
      dbm,
    };
  }

  private async getKnownNetworksPaths(): Promise<string[]> {
    const managedObjects = await this.getIwdManagedObjects();
    return Object.keys(managedObjects).filter(path => 
      managedObjects[path].hasOwnProperty(this.IWD_KNOWN_INTERFACE)
    );
  }
  
  async getAvailableNetworks() {
    const stationPath = await this.getStationPath();

    try {
      // Get current visible networks
      // GetOrderedNetworks returns [path, strength] tuples
      return this.dbusService.callMethod<[string, number][]>({
        serviceName: this.IWD_SERVICE,
        objectPath: stationPath,
        interfaceName: this.IWD_STATION_INTERFACE,
        methodName: WifiMethods.GET_ORDERED_NETWORKS,
        methodArgs: [],
      });
    } catch (error) {
      throw new InternalServerErrorException(`Failed to get available networks: ${error.message}`);
    }
  }

  async getNetworks(): Promise<WifiNetwork[]> {

    // 1. Get current visible networks
    const visibleNetworks = await this.getAvailableNetworks()

    // 2. Get all known (saved) network paths
    const knownPaths = await this.getKnownNetworksPaths();

    // 3. Get current network path
    const currentNetworkPath = await this.getCurrentNetworkPath();
    const currentNetworkHexId = currentNetworkPath ? this.getHexFromPath(currentNetworkPath) : null;

    // 4. Map and flag
    return visibleNetworks.map(([path, strength]) => {
      const formatted = this.formatNetwork(path, strength);
      // Logic: If the SSID/Security combo exists in KnownNetworks, it's known
      // If the path is the same as the current network path, it's connected
      return {
        ...formatted,
        isKnown: knownPaths.some(kp => this.getHexFromPath(kp) === this.getHexFromPath(path)),
        isConnected: !!currentNetworkHexId && this.getHexFromPath(path) === currentNetworkHexId,

      };
    });
  }

  async getCurrentNetworkPath(): Promise<string> {
    const stationPath = await this.getStationPath();
    let path = ''
    // Use DBus Properties interface to get ConnectedNetwork
    try {
      const connectedPathVariant = await this.dbusService.callMethod<DbusVariant<string>>({
        serviceName: this.IWD_SERVICE,
        objectPath: stationPath,
        interfaceName: this.DBUS_PROPERTIES_INTERFACE,
        methodName: DbusMethods.GET,
        methodArgs: [this.IWD_STATION_INTERFACE, 'ConnectedNetwork'],
      });
      path = connectedPathVariant.value;
    } catch (error) {
      this.logger.info('Connected network not found')
    }

    if (!path || path === '/') return '';

    return path
  }

  async subscribeToStationScanningStatus() {
    const stationPath = await this.getStationPath();
    const stationPropsChanged$ = await this.dbusService.subscribe<PropertiesChangedEvent>({
      serviceName: this.IWD_SERVICE,
      objectPath: stationPath,
      interfaceName: this.DBUS_PROPERTIES_INTERFACE,
      signal: Signals.PropertiesChanged,
    });

    this.stationScanningProp$ = stationPropsChanged$.pipe(
      filter(([iface, changed]) => iface === this.IWD_STATION_INTERFACE && 'Scanning' in changed),
      map(([_, changed]) => changed.Scanning.value as boolean),
      // tap((isScanning) => console.log('isScanning', isScanning)),
    );
  }

  async scan() {
    const stationPath = await this.getStationPath();
    try {
      // 1. Check if scan is already in progress
      const isScanning = await this.dbusService.callMethod<DbusVariant<boolean>>({
        serviceName: this.IWD_SERVICE,
        objectPath: stationPath,
        interfaceName: this.DBUS_PROPERTIES_INTERFACE,
        methodName: DbusMethods.GET,
        methodArgs: [this.IWD_STATION_INTERFACE, 'Scanning'],
      });      

      if (isScanning.value === true)  {
        // 2a. Create a stream to detect when ongoing scan is completed
        const notScanning$ = this.stationScanningProp$.pipe(
          filter(isScanning => isScanning === false),
          take(1),
          timeout({
            each: 5000,
            with: () => of(true),
          }),
        );
        this.logger.info('Scanning already in progress, waiting for it to complete');
        return firstValueFrom(notScanning$);
      } else {
        // 2b. Create a stream to detect when new scan is completed
        this.logger.info('Scanning not in progress, starting new scan');
        const scanCompleted$ = this.stationScanningProp$.pipe(
          skipWhile(isScanning => !isScanning),
          filter(isScanning => isScanning === false),
          take(1),
          timeout({
            each: 7000,
            with: () => of(true),
          }),
        );

        // 3b. Start new scan
        await this.dbusService.callMethod({
          serviceName: this.IWD_SERVICE,
          objectPath: stationPath,
          interfaceName: this.IWD_STATION_INTERFACE,
          methodName: WifiMethods.SCAN,
          methodArgs: [],
        });
  
        // 5b. Wait for scan to complete or timeout
        return firstValueFrom(scanCompleted$);
      }

      
    } catch (error) {
      throw new InternalServerErrorException(`Failed to scan: ${error.message}`);
    }
  }

  /**
   * Scenario 1: Connect to a network that IWD already has a password for.
   */
  async connectKnown(ssid: string): Promise<void> {
    const hexId = this.getHexFromSSID(ssid);
    const availableNetworks = await this.getAvailableNetworks();
    const availableNetworksPaths = availableNetworks.map(([path]) => path)
    const networkPath = availableNetworksPaths.find(path => this.getHexFromPath(path) === hexId);

    if (!networkPath) {
      throw new NotFoundException(`Known network with SSID ${ssid} not found`);
    }

    this.logger.info(`Attempting to connect to: ${ssid}`);
    try {
      await this.disconnect();
      await this.dbusService.callMethod({
        serviceName: this.IWD_SERVICE,
        objectPath: networkPath,
        interfaceName: this.IWD_NETWORK_INTERFACE,
        methodName: WifiMethods.CONNECT,
        methodArgs: [],
      });
      this.logger.info(`Connect command sent successfully to ${ssid}`);
    } catch (error) {
      this.logger.error(`Failed to connect: ${error.message}`);
      await this.connectFirstKnown();
      throw new InternalServerErrorException(`Failed to connect to wifi network ${ssid}`);
    }
  }

  /**
   * Scenario 2: Connect to a new network using the iwctl CLI.
   * This automatically handles the "Agent" requirement by passing the secret directly.
   */
  // TODO: Try to implement using dbus interface agent export
  async connectNew(ssid: string, passphrase: string): Promise<void> {
    this.logger.info(`Connecting to new network ${ssid} via CLI...`);
    const ifaceName = await this.getWifiInterfaceName();
    if (!ifaceName) {
      throw new NotFoundException('No wifi interface name found');
    }
    
    try {
      const { stderr } = await $`iwctl station ${ifaceName} connect ${ssid} --passphrase ${passphrase}`.quiet();
      const errorMessage = stderr.toString().trim();

      if (errorMessage !== '') {
        throw new Error(errorMessage);
      }

      this.logger.info(`Successfully connected to ${ssid}. It is now a 'Known' network.`);
    } catch (error) {
      this.logger.error(`Failed to connect to new network: ${error.message}`);
      await this.connectFirstKnown();
      throw new InternalServerErrorException(`Failed to connect to wifi network ${ssid}${error.message ? `: ${error.message}` : ''}`);
    }
  }

  private async connectFirstKnown(): Promise<void> {
    const knownNetworks = await this.getKnownNetworksPaths();
    if (knownNetworks.length === 0) {
      this.logger.debug('No known networks found');
      return;
    }
    const ssid = this.getSSIDFromPath(knownNetworks[0]);
    await this.connectKnown(ssid);
  }
  private getSSIDFromPath(path: string): string {
    const hexId = this.getHexFromPath(path);
    return Buffer.from(hexId, 'hex').toString('utf8');
  }

  private getHexFromPath(path: string): string {
    const parts = path.split('/');
    const segment = parts[parts.length - 1];
    return segment.substring(0, segment.lastIndexOf('_'));
  }

  private getHexFromSSID(ssid: string): string {
    return Buffer.from(ssid, 'utf8').toString('hex');
  }

  /**
   * Disconnects the station from the current network.
   */
  async disconnect(): Promise<void> {
    const stationPath = await this.getStationPath();
    this.logger.info(`Disconnecting station at: ${stationPath}`);
    try {
      await this.dbusService.callMethod({
        serviceName: this.IWD_SERVICE,
        objectPath: stationPath,
        interfaceName: this.IWD_STATION_INTERFACE,
        methodName: WifiMethods.DISCONNECT,
        methodArgs: [],
      });
      this.logger.info('Disconnected successfully');
    } catch (error) {
      this.logger.error(`Failed to disconnect: ${error.message}`);
      throw new InternalServerErrorException(`Failed to disconnect wifi network`);
    }
  }

  /**
   * Forgets a known network by deleting its configuration file.
   * This is useful for cleaning up the "double entries" or "ZTE_new 1" issues.
   */
  async forgetNetwork(ssid: string): Promise<void> {
    const hexId = this.getHexFromSSID(ssid);
    // KnownNetwork objects have a 'Forget' method
    // These paths usually look like /net/connman/iwd/0/26/known_network_id
    const knownPaths = await this.getKnownNetworksPaths();
    const knownNetworksPath = knownPaths.find(path => this.getHexFromPath(path) === hexId);
  
    if (!knownNetworksPath) {
      throw new NotFoundException(`Known network with SSID ${ssid} not found`);
    }

    const currentNetworkPath = await this.getCurrentNetworkPath();
    const currentNetPathId = this.getHexFromPath(currentNetworkPath);
    if ( currentNetPathId === hexId) {
      await this.disconnect()
    }
  
    try {
      await this.dbusService.callMethod({
        serviceName: this.IWD_SERVICE,
        objectPath: knownNetworksPath,
        interfaceName: this.IWD_KNOWN_INTERFACE,
        methodName: WifiMethods.FORGET,
        methodArgs: [],
      });
      this.logger.info(`Successfully forgot network ${ssid}`);
    } catch (error) {
      this.logger.error(`Failed to forget network ${ssid}: ${error.message}`);
      throw new InternalServerErrorException(`Failed to forget wifi network ${ssid}`);
    }
  }
}
