import { FileValidator } from '@nestjs/common';

export type FileExtensionValidatorOptions = {
  extensions: string[];
};

export class FileExtensionValidator extends FileValidator<
  FileExtensionValidatorOptions,
  any
> {
  buildErrorMessage(): string {
    return `Validation failed (expected extension is ${this.validationOptions.extensions.join(', ')})`;
  }

  isValid(file?: any): boolean {
    if (!this.validationOptions) {
      return true;
    }

    return (
      !!file &&
      !!this.validationOptions.extensions.some((extension) =>
        file.originalname.endsWith(extension),
      )
    );
  }
}
