import { Injectable, type OnModuleDestroy } from '@nestjs/common';
import { type TerminalSizeOptions } from '@scailx/shared';
import { Observable, Subject, Subscription } from 'rxjs';
import { wait } from 'src/common/utils';
import { createLogger } from 'src/utils';

@Injectable()
export class TerminalService implements OnModuleDestroy {
  private readonly logger = createLogger('TerminalService');

  private terminalProcesses: Map<string, Bun.Subprocess> = new Map();
  private terminalStdInSubs: Map<string, Subscription> = new Map();

  async onModuleDestroy() {
    this.terminalStdInSubs.forEach((sub) => {
      sub.unsubscribe();
    });

    await Promise.all(
      this.terminalProcesses
        .values()
        .map((process) => this.killTerminalProcess(process)),
    );
  }

  async initTerminalSession(
    sessionId: string,
    options?: TerminalSizeOptions,
  ): Promise<{ stdOut$: Observable<string>; stdIn$: Subject<string> }> {
    this.logger.info('Getting terminal...');
    const terminalStdOut$ = new Subject<string>();
    const terminalStdIn$ = new Subject<string>();

    const textDecoder = new TextDecoder();
    const terminalProcess = Bun.spawn(['bash', '--login'], {
      terminal: {
        cols: options?.cols || 80,
        rows: options?.rows || 24,
        data(_terminal, data) {
          // Called when data is received from the terminal
          terminalStdOut$.next(textDecoder.decode(data, { stream: true }));
        },
      },
      env: {
        ...Bun.env,
        LANG: 'en_US.UTF-8',
        LC_ALL: 'en_US.UTF-8',
      },
      cwd: Bun.env.HOME,
    });

    this.terminalProcesses.set(sessionId, terminalProcess);

    const terminalStdInSub = terminalStdIn$.subscribe((data) => {
      try {
        terminalProcess.terminal.write(data);
      } catch (error) {
        this.logger.error('Error writing data to terminal: ', error);
      }
    });
    this.terminalStdInSubs.set(sessionId, terminalStdInSub);
    return { stdOut$: terminalStdOut$.asObservable(), stdIn$: terminalStdIn$ };
  }

  private async killTerminalProcess(terminalProcess: Bun.Subprocess): Promise<void> {
    if (terminalProcess) {
      terminalProcess.kill('SIGINT');
      await Promise.race([terminalProcess.exited, wait(2000)]);
      if (!terminalProcess.killed) {
        terminalProcess.kill('SIGKILL');
        await terminalProcess.exited;
      }
    }
  }

  async closeTerminalSession(sessionId: string): Promise<void> {
    const terminalProcess = this.terminalProcesses.get(sessionId);
    if (terminalProcess) {
      await this.killTerminalProcess(terminalProcess);
      this.terminalProcesses.delete(sessionId);
      const terminalStdInSub = this.terminalStdInSubs.get(sessionId);
      if (terminalStdInSub) {
        terminalStdInSub.unsubscribe();
        this.terminalStdInSubs.delete(sessionId);
      }
    } else {
      this.logger.error(`Terminal session ${sessionId} not found`);
    }
  }
  async resizeTerminalSession(
    sessionId: string,
    cols: number,
    rows: number,
  ): Promise<void> {
    const terminalProcess = this.terminalProcesses.get(sessionId);
    if (terminalProcess) {
      terminalProcess.terminal.resize(cols, rows);
    } else {
      this.logger.error(`Terminal session ${sessionId} not found`);
    }
  }
}
