/**
 * Creates a deferred promise, exposing its resolve and reject methods outside the executor.
 * Useful for converting callback-style code to promise-based.
 */
export function defer<T = void>() {
  let resolve: (value: T | PromiseLike<T>) => void;
  let reject: (reason?: any) => void;

  const promise = new Promise<T>((res, rej) => {
    resolve = res;
    reject = rej;
  });

  // @ts-ignore - resolve and reject will always be initialized synchronously
  return { promise, resolve, reject };
}
