import { Controller, Get, Param, Query, UseGuards } from '@nestjs/common';
import { JwtAuthGuard } from 'src/auth/guards/jwt-auth.guard';
import type {
  AIProcessingPresetOption,
  Platform,
  PresetDto,
  PresetOption,
} from '../types';
import { PresetsService } from './presets.service';

@UseGuards(JwtAuthGuard)
@Controller('presets')
export class PresetsController {
  constructor(private readonly presetsService: PresetsService) {}

  @Get('inputs/list')
  async getInputPresetsList(): Promise<PresetOption[]> {
    const inputPresets = await this.presetsService.getInputPresetsList();
    return inputPresets;
  }

  @Get('ai-processing/list')
  async getAIProcessingPresetsList(): Promise<AIProcessingPresetOption[]> {
    const aiProcessingPresets = await this.presetsService.getAIProcessingPresetsList();
    return aiProcessingPresets;
  }

  @Get('outputs/list')
  async getOutputPresetsList(
    @Query('platform') platform: Platform,
    @Query('ai-preset') preset: string,
  ): Promise<PresetOption[]> {
    const outputPresets = await this.presetsService.getOutputPresetsList(
      platform,
      preset,
    );
    return outputPresets;
  }

  @Get('inputs/:name')
  async getInputPreset(@Param('name') name: string): Promise<PresetDto> {
    const inputPreset = await this.presetsService.getInputPreset(name);
    return inputPreset;
  }

  @Get('ai-processing/:platform/:name')
  async getAIProcessingPreset(
    @Param('platform') platform: Platform,
    @Param('name') name: string,
  ): Promise<PresetDto> {
    const aiProcessingPreset = await this.presetsService.getAIProcessingPreset(
      platform,
      name,
    );
    return aiProcessingPreset;
  }

  @Get('outputs/:name')
  async getOutputPreset(
    @Param('platform') platform: Platform,
    @Query('ai-preset') aiProcessingPresetName: string,
    @Param('name') name: string,
  ): Promise<PresetDto> {
    const outputPreset = await this.presetsService.getOutputPreset(
      platform,
      aiProcessingPresetName,
      name,
    );
    return outputPreset;
  }
}
