import { Injectable, InternalServerErrorException, Logger, type OnModuleInit } from "@nestjs/common";
import { EventEmitter2 } from "@nestjs/event-emitter";
import * as dbus from "dbus-next";
import { Observable, ReplaySubject } from "rxjs";
import { type DbusMethodParams, type DbusSubscribeParams } from "./types";

@Injectable()
export class DbusService implements OnModuleInit {
  private readonly logger = new Logger(DbusService.name);
  private bus: dbus.MessageBus;

  constructor(private eventEmitter: EventEmitter2) {}

  onModuleInit(): any {
    this.bus = dbus.systemBus();
    if (!this.bus) {
      this.logger.error("Failed to connect to the D-Bus system bus");
    }
  }

  async callMethod<T>({
    serviceName,
    objectPath,
    interfaceName,
    methodName,
    methodPath,
    methodArgs
  }: DbusMethodParams): Promise<T> {
    try {
      const proxyObject: dbus.ProxyObject = await this.bus.getProxyObject(serviceName, objectPath);
      const dbusInterface: any = proxyObject.getInterface(interfaceName);

      return methodPath !== undefined
        ? await dbusInterface[methodName](...methodArgs, methodPath)
        : await dbusInterface[methodName](...methodArgs);
    } catch (error) {
      this.logger.error(`Failed to call D-Bus method: ${error.message}`);
      throw new InternalServerErrorException(error.message);
    }
  }

  public async subscribe<EventData extends any[] = any[]>({ serviceName, objectPath, interfaceName, signal }: DbusSubscribeParams, tag?: string): Promise<Observable<EventData>> {
    try {
      const proxyObject: dbus.ProxyObject = await this.bus.getProxyObject(serviceName, objectPath);
      const dbusInterface = proxyObject.getInterface(interfaceName);

      const updatesChanel$ = new ReplaySubject<EventData>(1);
      dbusInterface.on(signal, (...data: EventData) => {
        if (tag) {
          this.eventEmitter.emit(`${tag}.changed`, data);
        }
          updatesChanel$.next(data);        
      });
      return updatesChanel$.asObservable();
    } catch (error) {
      this.logger.error(`Failed to subscribe to signals: ${error.message}`);
      throw new InternalServerErrorException(error.message);
    }
  }
}
