import { Injectable, type OnModuleDestroy, type OnModuleInit } from '@nestjs/common';
import { OnEvent } from '@nestjs/event-emitter';
import {
  PIPELINE_FILENAME,
  type DiskUsage,
  type NetworkStats,
  type NetworkStatsHistory,
  type NetworkStatsMetric,
  type Pipeline,
  type SDCardData,
  type Thresholds,
} from '@scailx/shared';
import { isNumber } from 'lodash';
import { resolve } from 'path';
import {
  catchError,
  firstValueFrom,
  interval,
  map,
  merge,
  of,
  skipWhile,
  startWith,
  Subject,
  Subscription,
  switchMap,
  throttleTime,
  timeout,
} from 'rxjs';
import { JsonSettingsService } from 'src/common/json/json.service';
import {
  appConfig,
  createLogger,
  getIsNPUUsed,
  getSDCardStatus,
  isHailoInstalled,
  oneHourMs,
  PIPELINE_FPS_EVENT_NAME,
  PIPELINE_LATENCY_EVENT_NAME,
  PIPELINE_STATUS_EVENT_NAME,
  THRESHOLDS_FILENAME,
} from 'src/utils';
import * as si from 'systeminformation';
import type {
  CPUHistory,
  CPUMetric,
  FPSMetric,
  MetricHistory,
  RAMMetric,
} from './types';

@Injectable()
export class MetricsService implements OnModuleInit, OnModuleDestroy {
  private readonly logger = createLogger('MetricsService');

  private cpuHistoryInterval: ReturnType<typeof setInterval>;
  private cpuMetricHistoryFilePath: string;

  private fpsHistoryFilePath: string;
  private fpsEvents$ = new Subject<number | null>();
  private fpsHistorySub: Subscription;

  private pipelineLatencyEvents$ = new Subject<number>();

  private ramUsageHistoryInterval: ReturnType<typeof setInterval>;
  private ramUsageHistoryFilePath: string;

  private networkStatsHistoryInterval: ReturnType<typeof setInterval>;
  private networkStatsHistoryFilePath: string;

  private pipelineStatus: string;

  constructor(private readonly jsonService: JsonSettingsService) {}

  async onModuleInit() {
    await this.jsonService.initSettings<Thresholds>(THRESHOLDS_FILENAME, {
      fps: 10,
      ram: 90,
      cpu: 90,
    });

    const scailxDataFolder = appConfig.SCAILX_PORTAL_PROJECT_DATA;
    if (!scailxDataFolder) {
      this.logger.warn(
        "SCAILX_PORTAL_PROJECT_DATA environment variable is not set, can't start cpu usage tool",
      );
      return;
    }

    this.cpuMetricHistoryFilePath = resolve(
      scailxDataFolder,
      'metrics',
      'cpu_usage.json',
    );
    const cpuUsageHistoryFile = await Bun.file(this.cpuMetricHistoryFilePath);
    const isCPUFileExists = await cpuUsageHistoryFile.exists();
    if (!isCPUFileExists) {
      await cpuUsageHistoryFile.write('[]');
    }
    await this.writeCpuHistory();

    this.cpuHistoryInterval = setInterval(async () => {
      await this.writeCpuHistory();
    }, 1000 * 60);

    this.fpsHistoryFilePath = resolve(scailxDataFolder, 'metrics', 'fps.json');
    const fpsHistoryFile = await Bun.file(this.fpsHistoryFilePath);
    const isFPSHistoryFileExists = await fpsHistoryFile.exists();
    if (!isFPSHistoryFileExists) {
      await fpsHistoryFile.write('[]');
    }

    const fpsHeartbeat$ = this.fpsEvents$.pipe(
      startWith(null), // Start timer immediately upon subscription
      switchMap(() =>
        interval(60000).pipe(
          // Instead of erroring, we emit a notification value
          map(() => null),
        ),
      ),
    );

    this.fpsHistorySub = merge(
      this.fpsEvents$.pipe(
        skipWhile((fps) => fps === 0), // wait for actual fps values after stream start
        throttleTime(60 * 1000),
      ),
      fpsHeartbeat$,
    ).subscribe(async (fps) => {
      await this.writeFPSHistory(fps);
    });

    this.ramUsageHistoryFilePath = resolve(
      scailxDataFolder,
      'metrics',
      'ram_usage.json',
    );
    const ramUsageHistoryFile = await Bun.file(this.ramUsageHistoryFilePath);
    const isRamUsageHistoryFileExists = await ramUsageHistoryFile.exists();
    if (!isRamUsageHistoryFileExists) {
      await ramUsageHistoryFile.write('[]');
    }

    await this.writeRamUsageHistory();
    this.ramUsageHistoryInterval = setInterval(async () => {
      await this.writeRamUsageHistory();
    }, 1000 * 60);

    this.networkStatsHistoryFilePath = resolve(
      scailxDataFolder,
      'metrics',
      'network_stats.json',
    );
    const networkStatsHistoryFile = await Bun.file(this.networkStatsHistoryFilePath);
    const isNetworkStatsHistoryFileExists = await networkStatsHistoryFile.exists();
    if (!isNetworkStatsHistoryFileExists) {
      await networkStatsHistoryFile.write('[]');
    }

    await this.writeNetworkStatsHistory();
    this.networkStatsHistoryInterval = setInterval(async () => {
      await this.writeNetworkStatsHistory();
    }, 1000 * 60);
  }

  async onModuleDestroy() {
    if (this.cpuHistoryInterval) {
      clearInterval(this.cpuHistoryInterval);
    }

    if (this.fpsHistorySub) {
      this.fpsHistorySub.unsubscribe();
    }

    if (this.ramUsageHistoryInterval) {
      clearInterval(this.ramUsageHistoryInterval);
    }

    if (this.networkStatsHistoryInterval) {
      clearInterval(this.networkStatsHistoryInterval);
    }
  }

  @OnEvent(PIPELINE_FPS_EVENT_NAME)
  onFPSEvent(fps: number) {
    this.fpsEvents$.next(fps);
  }

  @OnEvent(PIPELINE_STATUS_EVENT_NAME)
  onPipelineStatusEvent(status: string) {
    this.pipelineStatus = status;
  }

  @OnEvent(PIPELINE_LATENCY_EVENT_NAME)
  onPipelineLatencyEvent(latency: number) {
    this.pipelineLatencyEvents$.next(latency);
  }

  private async writeCpuHistory() {
    const values = await this.getCurrentCpuUsage();
    const historyEntries: CPUHistory[] = values.map((value, index) => ({
      timestamp: Date.now(),
      [index > 0 ? `CPU${index}` : 'CPU']: value,
    }));
    let cpuHistory = [];
    try {
      cpuHistory = (await Bun.file(
        this.cpuMetricHistoryFilePath,
      ).json()) as CPUHistory[];
    } catch (error) {
      this.logger.warn(`Can't read CPU usage history:`);
      this.logger.debug(error);
    }
    cpuHistory.push(...historyEntries);
    cpuHistory = cpuHistory.filter(
      (entry) => Date.now() - entry.timestamp <= oneHourMs,
    );
    await Bun.file(this.cpuMetricHistoryFilePath).write(
      JSON.stringify(cpuHistory, null, 2),
    );
  }

  private async writeFPSHistory(fps: number | null) {
    let fpsHistory = [];
    try {
      fpsHistory = (await Bun.file(this.fpsHistoryFilePath).json()) as MetricHistory[];
    } catch (error) {
      this.logger.warn(`Can't read FPS history:`);
      this.logger.debug(error);
    }
    if (isNumber(fps)) {
      fpsHistory.push({ timestamp: Date.now(), value: fps });
    }
    fpsHistory = fpsHistory.filter(
      (entry) => Date.now() - entry.timestamp <= oneHourMs,
    );
    await Bun.file(this.fpsHistoryFilePath).write(JSON.stringify(fpsHistory, null, 2));
  }

  private async writeRamUsageHistory() {
    const ramUsage = await this.getCurrentRamUsage();
    let ramUsageHistory = [];
    try {
      ramUsageHistory = (await Bun.file(
        this.ramUsageHistoryFilePath,
      ).json()) as MetricHistory[];
    } catch (error) {
      this.logger.warn(`Can't read RAM usage history:`);
      this.logger.debug(error);
    }
    ramUsageHistory.push({ timestamp: Date.now(), value: ramUsage });
    ramUsageHistory = ramUsageHistory.filter(
      (entry) => Date.now() - entry.timestamp <= oneHourMs,
    );
    await Bun.file(this.ramUsageHistoryFilePath).write(
      JSON.stringify(ramUsageHistory, null, 2),
    );
  }

  private async writeNetworkStatsHistory() {
    const networkStats = await this.getCurrentNetworkStats();
    let networkStatsHistory = [];
    try {
      networkStatsHistory = (await Bun.file(
        this.networkStatsHistoryFilePath,
      ).json()) as NetworkStatsHistory[];
    } catch (error) {
      this.logger.warn(`Can't read network stats history:`);
      this.logger.debug(error);
    }
    networkStatsHistory.push({ timestamp: Date.now(), value: networkStats });
    networkStatsHistory = networkStatsHistory.filter(
      (entry) => Date.now() - entry.timestamp <= oneHourMs,
    );
    await Bun.file(this.networkStatsHistoryFilePath).write(
      JSON.stringify(networkStatsHistory, null, 2),
    );
  }

  async getCurrentCpuUsage(): Promise<number[]> {
    const { currentLoad, cpus } = await si.currentLoad();
    const scailxEmbeddedBuildFolder = appConfig.SCAILX_EMBEDDED;
    if (!scailxEmbeddedBuildFolder) {
      this.logger.warn(
        "SCAILX_EMBEDDED environment variable is not set, can't read current CPU usage",
      );
      return;
    }

    return [currentLoad, ...cpus.map((cpu) => cpu.load)]
      .map((v) => Math.round(v * 10) / 10)
      .slice(0, 5);
  }

  async getCurrentRamUsage(): Promise<number> {
    const { total, active } = await si.mem();

    return Math.round((active / total) * 100);
  }

  async getCpuUsage(): Promise<CPUMetric> {
    const values = await this.getCurrentCpuUsage();

    let cpuHistory = [];
    try {
      cpuHistory = (await Bun.file(
        this.cpuMetricHistoryFilePath,
      ).json()) as CPUHistory[];
    } catch (error) {
      this.logger.warn(`Can't read CPU usage history:`);
      this.logger.error(error);
    }
    cpuHistory = cpuHistory.map((entry) => {
      const newEntry = {};
      for (const key in entry) {
        if (key.startsWith('CPU')) {
          const value: number = entry[key];
          newEntry[key] = Math.round(value * 10) / 10;
        }
      }
      newEntry['timestamp'] = entry.timestamp;
      return newEntry;
    });

    return {
      current: values,
      history: cpuHistory,
    };
  }

  async getDiskUsage(drive?: string): Promise<DiskUsage> {
    let fsSizeData = await si.fsSize(drive);

    if (!drive) {
      let sdCardData: SDCardData = { mountPoint: '', device: '' };
      try {
        sdCardData = await getSDCardStatus();
      } catch (error) {}

      if (sdCardData.mountPoint) {
        fsSizeData = fsSizeData.filter(({ mount }) => mount !== sdCardData.mountPoint);
      }
    }
    return fsSizeData.reduce(
      (acc, { size, available, used }) => {
        return {
          size: acc.size + size,
          available: acc.available + available,
          used: acc.used + used,
        };
      },
      { size: 0, available: 0, used: 0 },
    );
  }

  async getRamUsage(): Promise<RAMMetric> {
    const ramUsage = await this.getCurrentRamUsage();
    let ramUsageHistory = (await Bun.file(
      this.ramUsageHistoryFilePath,
    ).json()) as MetricHistory[];
    return {
      current: ramUsage,
      history: ramUsageHistory,
    };
  }

  async getCurrentNetworkStats(): Promise<NetworkStats> {
    const siNetworkStats = await si.networkStats();
    const networkStats = siNetworkStats.reduce(
      (acc, { rx_bytes, tx_bytes }) => {
        return {
          download: acc.download + rx_bytes,
          upload: acc.upload + tx_bytes,
        };
      },
      { download: 0, upload: 0 },
    );
    return {
      download: Math.round(networkStats.download / 1024 / 1024),
      upload: Math.round(networkStats.upload / 1024 / 1024),
    };
  }

  async getNetworkStats(): Promise<NetworkStatsMetric> {
    const networkStats = await this.getCurrentNetworkStats();
    let networkStatsHistory = (await Bun.file(
      this.networkStatsHistoryFilePath,
    ).json()) as NetworkStatsHistory[];
    return {
      current: networkStats,
      history: networkStatsHistory,
    };
  }

  async getNPUOn(): Promise<boolean> {
    try {
      const pipeline = await this.jsonService.readSettings<Pipeline>(PIPELINE_FILENAME);
      const tensorFilter = pipeline.components.find(
        (component) => component.data.type === 'tensor_filter',
      );
      if (!tensorFilter) return false;
      const customSetting = tensorFilter.data.settings?.custom;
      const acceleratorSetting = tensorFilter.data.settings?.accelerator;

      const vxDelegateLib = Bun.file('/usr/lib/libvx_delegate.so');
      const libFileExists = await vxDelegateLib.exists();
      const isNPUUsed = getIsNPUUsed(acceleratorSetting);
      return (
        this.pipelineStatus === 'running' &&
        libFileExists &&
        (customSetting === 'Delegate:External,ExtDelegateLib:libvx_delegate.so' ||
          customSetting ===
            'Delegate:External,ExtDelegateLib:/usr/lib/libvx_delegate.so') &&
        isNPUUsed
      );
    } catch (error) {
      this.logger.warn(`Can't read pipeline:`);
      this.logger.error(error);
      return false;
    }
  }

  async isHailoUsed(): Promise<boolean> {
    const pipeline = await this.jsonService.readSettings<Pipeline>(PIPELINE_FILENAME);
    const hailFilter = pipeline.components.find(
      (component) => component.data.type === 'hailofilter',
    );
    const hailoNet = pipeline.components.find(
      (component) => component.data.type === 'hailonet',
    );
    if (!hailFilter || !hailoNet) return false;
    return (
      this.pipelineStatus === 'running' &&
      !!hailoNet.data.settings?.['hef-path'] &&
      !!hailFilter.data.settings?.['so-path']
    );
  }

  async getCurrentProcessingMetrics(): Promise<{
    isNPUOn: boolean;
    isHailoOn?: boolean;
    timePerFrame: number;
  }> {
    const scailxEmbeddedBuildFolder = appConfig.SCAILX_EMBEDDED;
    if (!scailxEmbeddedBuildFolder) {
      this.logger.warn(
        "SCAILX_EMBEDDED environment variable is not set, can't read current Processing metrics",
      );
      return;
    }

    // const npuMetricFilePath = resolve(scailxEmbeddedBuildFolder, NPU_METRIC_FILENAME);
    const isNPUOn = await this.getNPUOn();

    let isHailoOn: boolean | undefined;
    const isHailoReadyToUse = await isHailoInstalled();
    if (isHailoReadyToUse) {
      isHailoOn = await this.isHailoUsed();
    }

    let timePerFrame = await firstValueFrom(
      this.pipelineLatencyEvents$.pipe(
        timeout(1000),
        catchError(() => of(0)),
      ),
    );
    return {
      isNPUOn,
      isHailoOn,
      timePerFrame,
    };
  }

  async getFPSMetric(): Promise<FPSMetric> {
    const currentFPSValue = await firstValueFrom(
      this.fpsEvents$.pipe(
        timeout(1000),
        catchError(() => of(null)),
      ),
    );

    let fpsHistory = [];
    try {
      fpsHistory = (await Bun.file(this.fpsHistoryFilePath).json()) as MetricHistory[];
      fpsHistory = fpsHistory.map(({ value, timestamp }) => ({
        value: Math.round(value * 10) / 10,
        timestamp,
      }));
    } catch (error) {
      this.logger.warn(`Can't read FPS history:`);
      this.logger.error(error);
    }

    return {
      current: isNumber(currentFPSValue) ? Math.round(currentFPSValue * 10) / 10 : null,
      history: fpsHistory,
    };
  }

  async getThresholds(): Promise<Thresholds> {
    const thresholds =
      await this.jsonService.readSettings<Thresholds>(THRESHOLDS_FILENAME);
    return thresholds;
  }
}
