import { readFileSync } from 'node:fs';
import { cwd } from 'node:process';

let accessTokenSecret = 'scailx-access-token-secret';
if (process.env.NODE_ENV === 'production') {
  try {
    accessTokenSecret = readFileSync(`${cwd()}/secrets/accessTokenSecret.key`, 'utf-8');
  } catch (e) {
    console.log('accessTokenSecret.key not found, using the default value...');
  }
}

export const JWT_SECRET = accessTokenSecret;

let refreshTokenSecret = 'scailx-refresh-token-secret';
if (process.env.NODE_ENV === 'production') {
  try {
    refreshTokenSecret = readFileSync(
      `${cwd()}/secrets/refreshTokenSecret.key`,
      'utf-8',
    );
  } catch (e) {
    console.log('refreshTokenSecret.key not found, using the default value...');
  }
}
export const JWT_REFRESH_SECRET = refreshTokenSecret;
