import { Controller, Get, Query, UseGuards } from '@nestjs/common';
import type { DiskUsage, NetworkStatsMetric, Thresholds } from '@scailx/shared';
import { Role } from '@scailx/shared';
import { JwtAuthGuard } from 'src/auth/guards';
import { Roles } from 'src/common/roles/roles.decorator';
import { RolesGuard } from 'src/common/roles/roles.guard';
import { MetricsService } from './metrics.service';
import type { CPUMetric, FPSMetric, ProcessingMetrics, RAMMetric } from './types';

@UseGuards(JwtAuthGuard, RolesGuard)
@Roles([Role.Admin, Role.PipelineOperator, Role.User])
@Controller('metrics')
export class MetricsController {
  constructor(private readonly metricsService: MetricsService) {}

  @Get('cpu')
  async getCPUUsage(): Promise<CPUMetric> {
    const cpuMetric = await this.metricsService.getCpuUsage();
    return cpuMetric;
  }

  @Get('processing')
  async getNPUMetric(): Promise<ProcessingMetrics> {
    const processingMetrics = await this.metricsService.getCurrentProcessingMetrics();
    return { current: processingMetrics };
  }

  @Get('fps')
  async getFPSMetric(): Promise<FPSMetric> {
    const fpsMetric = await this.metricsService.getFPSMetric();
    return fpsMetric;
  }

  @Get('disk-usage')
  async getDiskUsage(@Query('drive') drive?: string): Promise<DiskUsage> {
    const diskUsage = await this.metricsService.getDiskUsage(drive);
    return diskUsage;
  }

  @Get('ram-usage')
  async getRamUsage(): Promise<RAMMetric> {
    const ramUsage = await this.metricsService.getRamUsage();
    return ramUsage;
  }

  @Get('network-stats')
  async getNetworkStats(): Promise<NetworkStatsMetric> {
    const networkStats = await this.metricsService.getNetworkStats();
    return networkStats;
  }

  @Get('thresholds')
  async getThresholds(): Promise<Thresholds> {
    const thresholds = await this.metricsService.getThresholds();
    return thresholds;
  }
}
