import { Injectable, NotFoundException, UnauthorizedException } from '@nestjs/common';
import { JwtService } from '@nestjs/jwt';
import { Role } from '@scailx/shared';
import { type Request, type Response } from 'express';
import * as _ from 'lodash';
import { type User } from 'src/users/entities';
import { UsersService } from 'src/users/users.service';
import {
  convertTimeStringToMs,
  createLogger,
  JWT_REFRESH_SECRET,
  JWT_SECRET,
} from 'src/utils';
import type { JwtPayloadRefreshToken, TokensType } from './types';

@Injectable()
export class AuthService {
  private readonly logger = createLogger('AuthService');

  constructor(
    private readonly usersService: UsersService,
    private readonly jwtService: JwtService,
  ) {}

  async validateUser(username: string, pass: string): Promise<User | null> {
    const users = await this.usersService.getUsers();
    if (!users || users.length === 0) throw new NotFoundException('No users found');

    const user = users.find((user) => user.username === username);
    if (!user) throw new UnauthorizedException('Incorrect username or password');

    const isValidPassword = await Bun.password.verify(pass, user.hashedPassword);
    if (isValidPassword) {
      return user;
    }
    return null;
  }

  async login(user: User, res: Response) {
    this.logger.info(
      `login: user=${JSON.stringify(_.pick(user, 'id', 'username', 'roles'))}`,
    );
    const { username, id, roles } = user;

    const { accessToken, refreshToken } = await this.generateTokens(
      id,
      username,
      roles,
    );

    if (accessToken) {
      this.setTokenCookie(res, 'refreshToken', refreshToken);
      this.setTokenCookie(res, 'accessToken', accessToken);
      return { accessToken };
    }
  }

  async logout(res: Response): Promise<void> {
    res.clearCookie('refreshToken');
    res.clearCookie('accessToken');
  }

  async refresh(req: Request, res: Response): Promise<{ accessToken: string }> {
    const refreshToken = req.cookies?.refreshToken;
    const { id, username, roles } = await this.getJwtPayload(refreshToken);

    const { accessToken, refreshToken: newRefreshToken } = await this.generateTokens(
      id,
      username,
      roles,
    );

    this.setTokenCookie(res, 'refreshToken', newRefreshToken);
    this.setTokenCookie(res, 'accessToken', accessToken);

    return { accessToken };
  }

  private async getJwtPayload(refreshToken: string) {
    if (!refreshToken) throw new UnauthorizedException('Refresh token not found');

    let payload: JwtPayloadRefreshToken;
    try {
      payload = await this.jwtService.verifyAsync<JwtPayloadRefreshToken>(
        refreshToken,
        {
          secret: JWT_REFRESH_SECRET,
        },
      );
    } catch (error) {
      throw new UnauthorizedException('Invalid refresh token');
    }
    return payload;
  }

  private async generateTokens(
    id: string,
    username: string,
    roles: Role[],
  ): Promise<TokensType> {
    const [accessToken, refreshToken] = await Promise.all([
      this.jwtService.signAsync(
        {
          id,
          username,
          roles,
        },
        {
          secret: JWT_SECRET,
          expiresIn: '2h',
        },
      ),
      this.jwtService.signAsync(
        {
          id,
          username,
          roles,
        },
        {
          secret: JWT_REFRESH_SECRET,
          expiresIn: '7d',
        },
      ),
    ]);

    return { accessToken, refreshToken };
  }

  private setTokenCookie(res: Response, name: string, token: string): void {
    res.cookie(name, token, {
      httpOnly: true,
      maxAge: convertTimeStringToMs('7d'),
      sameSite: 'lax',
    });
  }
}
