import { ValidationPipe } from '@nestjs/common';
import { NestFactory } from '@nestjs/core';
import { DocumentBuilder, SwaggerModule } from '@nestjs/swagger';
import { API_PREFIX, type ReverseProxyConfig } from '@scailx/shared';
import { $ } from 'bun';
import cookieParser from 'cookie-parser';
import { WinstonModule } from 'nest-winston';
import { readFileSync } from 'node:fs';
import { resolve } from 'node:path';
import { AppModule } from './app.module';
import { JsonSettingsService } from './common/json/json.service';
import { HttpExceptionFilter } from './http-exception.filter';
import { PipelineService } from './pipeline/pipeline.service';
import {
  appConfig,
  createLogger,
  JWT_SECRET,
  startBunNativeProxy,
  type ProxyWsData,
} from './utils';

const tlsKeyPath = resolve(process.cwd(), './secrets/cert.key');
const tlsCertPath = resolve(process.cwd(), './secrets/cert.pem');

async function bootstrap() {
  const devMode = appConfig.NODE_ENV === 'development';
  const prodMode = appConfig.NODE_ENV === 'production';

  const logger = createLogger('Nest');
  const isHTTPSOn = prodMode && appConfig.HTTPS;

  const app = await NestFactory.create(AppModule, {
    logger: WinstonModule.createLogger({
      instance: logger,
    }),
    httpsOptions: isHTTPSOn
      ? {
          key: readFileSync(tlsKeyPath),
          cert: readFileSync(tlsCertPath),
          passphrase: 'Angry3-Pick-Rough-Truck-Unit',
        }
      : undefined,
  });

  app.enableShutdownHooks(['SIGINT', 'SIGTERM', 'SIGHUP']);
  app.use(cookieParser());
  app.enableCors({ origin: true, credentials: true });

  app.useGlobalPipes(
    new ValidationPipe({
      // whitelist: true,
      transform: true,
      transformOptions: {
        enableImplicitConversion: true,
      },
    }),
  );

  app.useGlobalFilters(new HttpExceptionFilter());

  app.setGlobalPrefix(API_PREFIX);

  const pipelineService = app.get(PipelineService);
  const jsonService = app.get(JsonSettingsService);
  const reverseProxyConfig =
    await jsonService.readSettings<ReverseProxyConfig[]>('reverse-proxy.config');

  const proxies: Bun.Server<ProxyWsData>[] = [];

  for (const config of reverseProxyConfig) {
    if (devMode && !config.dev) continue;

    if (prodMode && !appConfig.SCAILX_PORTAL_RUNNING_ON_PC) {
      // killing hanging proxies
      try {
        await $`sudo lsof -t -i :${config.proxyPort} | xargs sudo kill -9`.quiet();
      } catch (error) {
        logger.warn(`Failed to kill hanging proxy on port ${config.proxyPort}`);
      }
    }

    const proxyLogger = createLogger(`[bun-proxy:${config.name}]`);

    proxies.push(
      startBunNativeProxy(
        {
          name: config.name,
          proxyPort: config.proxyPort,
          target: `http://127.0.0.1:${config.originalPort}`,
          jwtSecret: JWT_SECRET,
          cookieName: 'accessToken', // matches your middleware
          tls: isHTTPSOn
            ? {
                key: tlsKeyPath,
                cert: tlsCertPath,
              }
            : undefined,
        },
        proxyLogger,
      ),
    );
  }

  process.on('exit', async () => {
    for (const proxy of proxies) {
      await proxy.stop();
    }
    await app.close();
  });

  // Swagger setup
  const swaggerConfig = new DocumentBuilder()
    .setTitle('Scailx API')
    .setDescription('API documentation for Scailx backend')
    .setVersion('1.0')
    .addBearerAuth()
    .build();
  const document = SwaggerModule.createDocument(app, swaggerConfig);
  SwaggerModule.setup('api/docs', app, document);
  // Save swagger.json
  import('fs').then((fs) => {
    fs.writeFileSync('swagger.json', JSON.stringify(document, null, 2));
  });

  const port = appConfig.PORT;
  await app.listen(port, '0.0.0.0');
  if (prodMode) {
    pipelineService.init();
  }
}
bootstrap();
