import type { LogSource } from '@scailx/shared';
import { resolve } from 'path';
import stripAnsi from 'strip-ansi';
import {
  createLogger as createWinstonLogger,
  format,
  Logger,
  transports,
} from 'winston';
import DailyRotateFile from 'winston-daily-rotate-file';
import { appConfig } from './appConfig';

const consoleFormat = format.printf(({ level, message, service, timestamp, stack }) => {
  return `${timestamp} ${level.toUpperCase()} [${service}]: ${message} ${stack ? stack : ''}`;
});

const fileFormat = format.printf(
  ({ level, message, service, timestamp, stack, source }) => {
    return JSON.stringify({
      level,
      message: stripAnsi(message as string),
      service,
      timestamp,
      stack,
      source,
    });
  },
);

let instance: Logger;

export const getLoggerPath = () => {
  if (appConfig.NODE_ENV === 'production') {
    // return appConfig.SCAILX_PORTAL_RUNNING_ON_PC ? resolve('../..', 'tmp', 'scailx-ai-portal', 'logs') : resolve('/', 'var', 'log', 'scailx-ai-portal');
    return resolve('../..', 'tmp', 'scailx-ai-portal', 'logs');
  } else {
    return resolve(process.cwd(), '..', '..', 'logs');
  }
};

export const createLogger = (name: string, source: LogSource = 'web') => {
  if (!instance) {
    let loggerPath = getLoggerPath();
    // console.log('loggerPath', loggerPath);
    instance = createWinstonLogger({
      transports: [
        new DailyRotateFile({
          level: 'debug',
          filename: resolve(loggerPath, 'server-%DATE%.log'),
          maxSize: '1m',
          datePattern: 'YYYY-MM-DD',
          maxFiles: '7d',
          format: format.combine(
            format.timestamp({ format: 'YYYY-MM-DD HH:mm:ss' }),
            format.errors({ stack: true }),
            fileFormat,
          ),
        }),
        new transports.Console({
          level: 'info',
          format: format.combine(
            format.timestamp({ format: 'YYYY-MM-DD HH:mm:ss A' }),
            format.colorize({ message: true }),
            format.errors({ stack: true }),
            consoleFormat,
          ),
        }),
      ],
    });
  }
  return instance.child({ service: name, source });
};

export const readStream = async (
  stream: ReadableStream | number,
  log: (msg: string) => void,
) => {
  if (stream instanceof ReadableStream) {
    const reader = stream.getReader();
    const decoder = new TextDecoder();
    while (true) {
      const { done, value } = await reader.read();
      if (done) break;
      log(decoder.decode(value, { stream: true }));
    }
  }
};
