import { $ } from 'bun';
import { resolve } from 'path';
import { appConfig } from './appConfig';

export const isHailoAccInstalled = async () => {
  try {
    const isHailoAccInstalled = await $`lspci | grep -i hailo`.quiet().text();
    return isHailoAccInstalled.trim() !== '';
  } catch (error) {
    return false;
  }
};

export const isHailoSDKInstalled = async () => {
  try {
    const isHailoInstalled = await $`hailortcli -v`.quiet().text();
    return isHailoInstalled.trim() !== '';
  } catch (error) {
    return false;
  }
};

export const isHailoInstalled = async () => {
  try {
    return (await isHailoSDKInstalled()) && (await isHailoAccInstalled());
  } catch (error) {
    return false;
  }
};

export const getIsNPUUsed = (acceleratorSetting: unknown | undefined) => {
  const acceleratorSettingString = String(acceleratorSetting) as string;
  if (!acceleratorSettingString || !acceleratorSettingString.startsWith('true'))
    return false;
  const acceleratorSettingBackendsValue = acceleratorSettingString.split(':')[1];
  if (!acceleratorSettingBackendsValue) return false;
  const acceleratorBackends = acceleratorSettingBackendsValue.split(',');
  return acceleratorBackends.includes('npu');
};

export const getSDCardStatus = async () => {
  const scailxEmbeddedFolder = appConfig.SCAILX_EMBEDDED;
  if (!scailxEmbeddedFolder) {
    throw new Error(
      "SCAILX_EMBEDDED environment variable is not set, can't read SDCard path",
    );
  }
  const scriptPath = resolve(scailxEmbeddedFolder, 'usr', 'bin', 'explore_sd.py');
  let result = '';
  try {
    result = await $`python3 ${scriptPath}`.quiet().text();
  } catch (error) {
    throw new Error("Can't read SDCard path");
  }
  if (!result) return { device: '', mountPoint: '' };
  const [device, mountPoint] = result.split(' ').map((item) => item.trim());
  return { device, mountPoint };
};
