import { UseGuards, type OnModuleDestroy } from '@nestjs/common';
import { ConnectedSocket, MessageBody, SubscribeMessage, WebSocketGateway } from '@nestjs/websockets';
import { Role, type TerminalSizeOptions } from '@scailx/shared';
import { concatMap, type Subject, type Subscription } from 'rxjs';
import { Socket } from "socket.io";
import { WsJwtGuard } from 'src/auth/guards/ws-jwt.guard';
import { Roles } from 'src/common/roles/roles.decorator';
import { RolesGuard } from 'src/common/roles/roles.guard';
import { createLogger } from 'src/utils';
import { TerminalService } from './terminal.service';

@UseGuards(WsJwtGuard, RolesGuard)
@Roles([Role.Admin])
@WebSocketGateway({ cors: { origin: "*", credentials: true } })
export class TerminalGateway implements OnModuleDestroy {

  private readonly logger = createLogger('TerminalGateway');

  private stdOutSubs: Map<string, Subscription> = new Map();
  private stdIn$Map: Map<string, Subject<string>> = new Map();

  constructor(private readonly terminalService: TerminalService) {}

  onModuleDestroy() {
    this.stdOutSubs.forEach((sub) => {
      sub.unsubscribe();
    });
  }

  @SubscribeMessage('initTerminal')
  async handleInitTerminal(@ConnectedSocket() client: Socket, @MessageBody() body: TerminalSizeOptions): Promise<{ sessionId: string }> {
    const sessionId = crypto.randomUUID();
    const { stdOut$, stdIn$ } = await this.terminalService.initTerminalSession(sessionId, body);

    const stdOutSub = stdOut$.pipe(
      concatMap((data) => {
        return new Promise<void>((resolve) => {
          client.emit('terminalSession', { sessionId, data }, () => {
            resolve();
          });
        });
      })
    ).subscribe();
    this.stdOutSubs.set(sessionId, stdOutSub);
    this.stdIn$Map.set(sessionId, stdIn$);
    return { sessionId };
  }

  @SubscribeMessage('terminalSession')
  async handleTerminalSession(@MessageBody() body: { sessionId: string, data: string }): Promise<void> {
    const { sessionId, data } = body;
    const stdIn$ = this.stdIn$Map.get(sessionId);
    if (stdIn$) {
      stdIn$.next(data);
    } else {
      this.logger.error(`Terminal session ${sessionId} not found`);
    }
  }

  @SubscribeMessage('closeTerminal')
  async handleCloseTerminal(@MessageBody() body: { sessionId: string }): Promise<void> {
    const { sessionId } = body;
    await this.terminalService.closeTerminalSession(sessionId);
  
    const stdIn$ = this.stdIn$Map.get(sessionId);
    const stdOutSub = this.stdOutSubs.get(sessionId);
    if (stdIn$) {
      this.stdIn$Map.delete(sessionId);
    }

    if (stdOutSub) {
      stdOutSub.unsubscribe();
      this.stdOutSubs.delete(sessionId);
    }
  }

  @SubscribeMessage('resizeTerminal')
  async handleResizeTerminal(@MessageBody() body: { sessionId: string, cols: number, rows: number }): Promise<void> {
    const { sessionId, cols, rows } = body;
    await this.terminalService.resizeTerminalSession(sessionId, cols, rows);
  }
}
