import { Body, Controller, Delete, Get, Param, Post, Put, UseGuards } from '@nestjs/common';
import { Role } from '@scailx/shared';
import { JwtAuthGuard } from 'src/auth/guards';
import { Roles } from 'src/common/roles/roles.decorator';
import { RolesGuard } from 'src/common/roles/roles.guard';
import { WifiService } from './wifi.service';

@UseGuards(JwtAuthGuard, RolesGuard)
@Roles([Role.Admin])
@Controller('wifi')
export class WifiController {

  constructor(private readonly wifiService: WifiService) {}

  @Get('interface-name')
  async getInterfaceName() {
    return this.wifiService.getWifiInterfaceName();
  }

  @Get('networks')
  async getNetworks() {
    await this.wifiService.scan();
    return this.wifiService.getNetworks();
  }

  @Post('networks')
  async connectNew(@Body() body: { ssid: string, passphrase: string }) {
    await this.wifiService.disconnect();
    const { ssid, passphrase } = body;
    return this.wifiService.connectNew(ssid, passphrase);
  }

  @Put('networks/:ssid/connect')
  async connectKnown(@Param('ssid') ssid: string) {
    return this.wifiService.connectKnown(ssid);
  }

  @Put('networks/disconnect')
  async disconnect() {
    return this.wifiService.disconnect();
  }

  @Delete('networks/:ssid')
  async forgetNetwork(@Param('ssid') ssid: string) {
    return this.wifiService.forgetNetwork(ssid);
  }
}
