import {
  Body,
  Controller,
  Delete,
  Get,
  HttpCode,
  HttpStatus,
  Param,
  ParseUUIDPipe,
  Patch,
  Put,
  Res,
  UseGuards,
} from '@nestjs/common';
import { Role, type UserBase } from '@scailx/shared';
import { type Response } from 'express';
import { JwtAuthGuard } from 'src/auth/guards/jwt-auth.guard';
import { GetUser } from 'src/common/decorators';
import { Roles } from 'src/common/roles/roles.decorator';
import { RolesGuard } from 'src/common/roles/roles.guard';
import { ChangePasswordDto, CreateUserDto, PutManyUserDto, UpdateUserDto } from './dto';
import { UsersService } from './users.service';

@UseGuards(JwtAuthGuard, RolesGuard)
@Controller('users')
export class UsersController {
  constructor(private readonly usersService: UsersService) {}

  @HttpCode(HttpStatus.CREATED)
  @Put()
  @Roles([Role.Admin])
  create(@Body() createUserDtos: CreateUserDto[]): Promise<UserBase[]> {
    return this.usersService.createMany(createUserDtos);
  }

  @Patch()
  @Roles([Role.Admin])
  createOrUpdateManyByUsername(
    @Body() putManyUsersDto: PutManyUserDto[],
  ): Promise<UserBase[]> {
    return this.usersService.createOrUpdateManyByUsername(putManyUsersDto);
  }

  @HttpCode(HttpStatus.OK)
  @Get()
  @Roles([Role.Admin])
  findAll(): Promise<UserBase[]> {
    return this.usersService.findAll();
  }

  @HttpCode(HttpStatus.OK)
  @Get(':id')
  @Roles([Role.Admin])
  findOne(@Param('id', new ParseUUIDPipe()) id: string): Promise<UserBase> {
    return this.usersService.findOne(id);
  }

  @HttpCode(HttpStatus.CREATED)
  @Patch(':id')
  @Roles([Role.Admin])
  update(
    @Param('id', new ParseUUIDPipe()) id: string,
    @Body() updateUserDto: UpdateUserDto,
  ): Promise<UserBase> {
    return this.usersService.updateOneById(id, updateUserDto);
  }

  @HttpCode(HttpStatus.CREATED)
  @Patch('change-password/:id')
  @Roles([Role.Admin, Role.User, Role.PipelineOperator])
  changePassword(
    @Param('id', new ParseUUIDPipe()) id: string,
    @Body() changePasswordDto: ChangePasswordDto,
  ): Promise<UserBase> {
    return this.usersService.changePasswordById(id, changePasswordDto);
  }

  @Delete(':id')
  @Roles([Role.Admin])
  async remove(
    @Param('id', new ParseUUIDPipe()) id: string,
    @GetUser('id', ParseUUIDPipe) currentUserId: string,
    @Res() res: Response,
  ): Promise<void | UserBase> {
    const result = await this.usersService.removeOneById(id, currentUserId);
    if (result) {
      res.status(HttpStatus.OK).send(result);
    } else {
      res.status(HttpStatus.NO_CONTENT).send();
    }
  }

  @HttpCode(HttpStatus.OK)
  @Delete()
  @Roles([Role.Admin])
  async removeManyByUsername(
    @Body() usernames: string[],
    @GetUser('username') currentUsername: string,
  ): Promise<UserBase[]> {
    return this.usersService.removeManyByUsername(usernames, currentUsername);
  }
}
