import { Controller, Get, Param, UseGuards } from '@nestjs/common';
import type { Plugin } from '@scailx/shared';
import { Role } from '@scailx/shared';
import { JwtAuthGuard } from 'src/auth/guards';
import { Roles } from 'src/common/roles/roles.decorator';
import { RolesGuard } from 'src/common/roles/roles.guard';
import { PluginsService } from './plugins.service';

@UseGuards(JwtAuthGuard, RolesGuard)
@Controller('plugins')
export class PluginsController {
  constructor(private readonly pluginsService: PluginsService) {}
  @Roles([Role.Admin, Role.PipelineOperator])
  @Get()
  async getPlugins(): Promise<Plugin[]> {
    const plugins = await this.pluginsService.getPlugins();
    return plugins;
  }

  @Roles([Role.Admin, Role.PipelineOperator])
  @Get('list')
  async getPluginsList(): Promise<string[]> {
    const plugins = await this.pluginsService.getPluginsList();
    return plugins;
  }

  @Roles([Role.Admin, Role.PipelineOperator])
  @Get(':name')
  async getPlugin(@Param('name') name: string): Promise<Plugin> {
    const plugin = await this.pluginsService.getPlugin(name);
    return plugin;
  }
}
